import sys, struct
class BR:
    def __init__(s,d,pos=0): s.d=d; s.p=pos*8
    def bits(s,n):
        v=0
        for _ in range(n):
            v=(v<<1)|((s.d[s.p>>3]>>(7-(s.p&7)))&1); s.p+=1
        return v
    def sbits(s,n):
        v=s.bits(n)
        if n and v>>(n-1): v-=1<<n
        return v
    def align(s): s.p=(s.p+7)&~7
    def bytepos(s): return s.p>>3
    def utf8(s):
        b=s.bits(8)
        if b<0x80: return b
        n=0
        while b&(0x80>>n): n+=1
        v=b&(0x7f>>n)
        for _ in range(n-1): v=(v<<6)|(s.bits(8)&0x3f)
        return v
def dump(path, verbose=True, maxframes=1000000):
    d=open(path,'rb').read()
    assert d[:4]==b'fLaC'
    p=4; info={}
