            if verbose: print('STREAMINFO',info)
        elif t==4:
            if verbose:
                vl=struct.unpack('<I',body[:4])[0]; vendor=body[4:4+vl]; q=4+vl; n=struct.unpack('<I',body[q:q+4])[0]; q+=4; cm=[]
                for i in range(n):
                    l=struct.unpack('<I',body[q:q+4])[0]; cm.append(body[q+4:q+4+l].decode()); q+=4+l
                print('VORBIS_COMMENT',vendor,cm)
        else:
            if verbose: print('BLOCK type',t,'len',ln)
        p+=4+ln
        if last: break
    frames=[]
    fi=0
    while p<len(d) and fi<maxframes:
        br=BR(d,p)
        sync=br.bits(15); assert sync==0x7ffc, (hex(sync),p)
        bs_strategy=br.bits(1); bsc=br.bits(4); src=br.bits(4); chm=br.bits(4); ssc=br.bits(3); br.bits(1)
        fnum=br.utf8()
        if bsc==1: bs=192
        elif 2<=bsc<=5: bs=576<<(bsc-2)
        elif bsc==6: bs=br.bits(8)+1
        elif bsc==7: bs=br.bits(16)+1
        else: bs=256<<(bsc-8)
        srtab=[None,88200,176400,192000,8000,16000,22050,24000,32000,44100,48000,96000]
        if src<12: sr=srtab[src]
        elif src==12: sr=br.bits(8)*1000
        elif src==13: sr=br.bits(16)
        else: sr=br.bits(16)*10
        bpst=[None,8,12,None,16,20,24,32]
        bps=bpst[ssc] or info['bps']
        crc8=br.bits(8)
        nch = chm+1 if chm<8 else 2
        subs=[]
        for c in range(nch):
            br.bits(1); st=br.bits(6); w=br.bits(1); wb=0
            if w:
                while br.bits(1)==0: wb+=1
                wb+=1
            cb=bps-wb
            if chm==8 and c==1 or chm==9 and c==0 or chm==10 and c==1: cb+=1
            desc=''
            if st==0:
                v=br.sbits(cb); desc='CONST %d'%v
            elif st==1:
                for i in range(bs): br.sbits(cb)
                desc='VERBATIM'
            elif 8<=st<=12:
                order=st-8
                for i in range(order): br.sbits(cb)
                desc='FIXED o=%d'%order
            elif st>=32:
                order=(st&31)+1
                for i in range(order): br.sbits(cb)
                prec=br.bits(4)+1; shift=br.sbits(5)
                coefs=[br.sbits(prec) for i in range(order)]
                desc='LPC o=%d prec=%d shift=%d coefs=%s'%(order,prec,shift,coefs)
            else: desc='RESERVED %d'%st
            if st==1 or 8<=st<=12 or st>=32:
                order = 0 if st==1 else (st-8 if st<32 else (st&31)+1)
                if st!=1:
                    meth=br.bits(2); po=br.bits(4); pbits=4 if meth==0 else 5; esc=(1<<pbits)-1
                    params=[]
                    for part in range(1<<po):
                        k=br.bits(pbits)
                        n=(bs>>po) - (order if part==0 else 0)
                        if k==esc:
                            rb=br.bits(5); params.append('esc%d'%rb)
                            for i in range(n): br.bits(rb)
                        else:
                            params.append(k)
                            for i in range(n):
                                q=0
                                while br.bits(1)==0: q+=1
                                br.bits(k)
                    desc+=' rice%d po=%d params=%s'%(meth,po,params)
            subs.append(desc)
            if w: subs[-1]+=' wasted=%d'%wb
        br.align()
        crc16=br.bits(16)
        end=br.bytepos()
        frames.append((fnum,bs,sr,chm,bps,end-p,subs))
        if verbose:
            print('FRAME %d bs=%d sr=%s chm=%d bps=%d size=%d'%(fnum,bs,sr,chm,bps,end-p))
            for s_ in subs: print('   ',s_[:300])
        p=end; fi+=1
    return info,frames
if __name__=='__main__':
    dump(sys.argv[1], maxframes=int(sys.argv[2]) if len(sys.argv)>2 else 1000000)
