#ifndef COMMON_H
#define COMMON_H
#include <stdint.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MIN(a,b) ((a)<(b)?(a):(b))
#define MAX(a,b) ((a)>(b)?(a):(b))
#define ARRAY_ELEMS(a) (sizeof(a)/sizeof((a)[0]))

static inline int ilog2(unsigned v) { return v ? 31 - __builtin_clz(v) : 0; }
static inline int ilog2_64(uint64_t v) { return v ? 63 - __builtin_clzll(v) : 0; }
static inline int clip_int(int v, int lo, int hi) { return v < lo ? lo : v > hi ? hi : v; }

/* dynamic byte buffer */
typedef struct {
    uint8_t *data;
    size_t len, cap;
} ByteBuf;

static inline void bb_reserve(ByteBuf *b, size_t extra) {
    if (b->len + extra > b->cap) {
        size_t nc = b->cap ? b->cap * 2 : 4096;
        while (nc < b->len + extra) nc *= 2;
        b->data = realloc(b->data, nc);
        b->cap = nc;
    }
}
static inline void bb_put(ByteBuf *b, const void *p, size_t n) { bb_reserve(b, n); memcpy(b->data + b->len, p, n); b->len += n; }
static inline void bb_putc(ByteBuf *b, int c) { bb_reserve(b, 1); b->data[b->len++] = (uint8_t)c; }
static inline void bb_free(ByteBuf *b) { free(b->data); b->data = NULL; b->len = b->cap = 0; }

/* little/big endian helpers */
static inline uint32_t rl16(const uint8_t *p) { return p[0] | (p[1] << 8); }
static inline uint32_t rl24(const uint8_t *p) { return p[0] | (p[1] << 8) | (p[2] << 16); }
static inline uint32_t rl32(const uint8_t *p) { return p[0] | (p[1] << 8) | (p[2] << 16) | ((uint32_t)p[3] << 24); }
static inline uint64_t rl64(const uint8_t *p) { return rl32(p) | ((uint64_t)rl32(p + 4) << 32); }
static inline uint32_t rb16(const uint8_t *p) { return (p[0] << 8) | p[1]; }
static inline uint32_t rb24(const uint8_t *p) { return (p[0] << 16) | (p[1] << 8) | p[2]; }
static inline uint32_t rb32(const uint8_t *p) { return ((uint32_t)p[0] << 24) | (p[1] << 16) | (p[2] << 8) | p[3]; }
static inline void wl16(uint8_t *p, uint32_t v) { p[0] = v; p[1] = v >> 8; }
static inline void wl24(uint8_t *p, uint32_t v) { p[0] = v; p[1] = v >> 8; p[2] = v >> 16; }
static inline void wl32(uint8_t *p, uint32_t v) { p[0] = v; p[1] = v >> 8; p[2] = v >> 16; p[3] = v >> 24; }
static inline void wl64(uint8_t *p, uint64_t v) { wl32(p, (uint32_t)v); wl32(p + 4, (uint32_t)(v >> 32)); }
static inline void wb16(uint8_t *p, uint32_t v) { p[0] = v >> 8; p[1] = v; }
