#ifndef BITIO_H
#define BITIO_H
#include "common.h"

/* Bit writer (MSB first) */
typedef struct {
    uint8_t *buf;
    size_t cap;         /* bytes */
    size_t pos;         /* bit position */
} BitWriter;

static inline void bw_init(BitWriter *w, uint8_t *buf, size_t cap) { w->buf = buf; w->cap = cap; w->pos = 0; memset(buf, 0, cap); }
static inline void bw_put(BitWriter *w, uint32_t v, int n) {
