/* FLAC encoder: original implementation modelled on observed behaviour of the
 * reference tool (bit-exact output). */
#include <math.h>
#include <limits.h>
#include "flacenc.h"
#include "bitio.h"

#define SUB_CONSTANT 0
#define SUB_VERBATIM 1
#define SUB_FIXED    8
#define SUB_LPC      32

#define MIN_LPC_SHIFT 0
#define MAX_LPC_SHIFT 15

static const int flac_blocksize_table[16] = {
    0, 192, 576 << 0, 576 << 1, 576 << 2, 576 << 3, 0, 0,
    256 << 0, 256 << 1, 256 << 2, 256 << 3, 256 << 4, 256 << 5, 256 << 6, 256 << 7
};
static const int flac_sample_rate_table[16] = {
    0, 88200, 176400, 192000, 8000, 16000, 22050, 24000, 32000, 44100, 48000, 96000, 0, 0, 0, 0
};

void flacenc_default_options(FlacEncOptions *o)
{
    memset(o, 0, sizeof *o);
    o->compression_level = -1;
    o->frame_size = 0;
    o->lpc_coeff_precision = 15;
