            if (opt->max_prediction_order > FLAC_MAX_FIXED_ORDER) {
                snprintf(errmsg, errlen, "invalid max prediction order: %d", opt->max_prediction_order);
                return -1;
            }
        } else if (opt->max_prediction_order < 1 || opt->max_prediction_order > FLAC_MAX_LPC_ORDER) {
            snprintf(errmsg, errlen, "invalid max prediction order: %d", opt->max_prediction_order);
            return -1;
        }
        enc->max_pred_order = opt->max_prediction_order;
    }
    if (enc->max_pred_order < enc->min_pred_order) {
        snprintf(errmsg, errlen, "invalid prediction orders: min=%d max=%d", enc->min_pred_order, enc->max_pred_order);
        return -1;
    }
    if (opt->prediction_order_method >= 0) enc->order_method = opt->prediction_order_method;
    if (opt->min_partition_order >= 0) enc->min_part_order = opt->min_partition_order;
    if (opt->max_partition_order >= 0) enc->max_part_order = opt->max_partition_order;
    if (enc->max_part_order < enc->min_part_order) {
        snprintf(errmsg, errlen, "invalid partition orders: min=%d max=%d", enc->min_part_order, enc->max_part_order);
        return -1;
    }

    if (opt->frame_size > 0) {
        enc->blocksize = opt->frame_size;
        if (enc->blocksize < 16 || enc->blocksize > FLAC_MAX_BLOCKSIZE) {
            snprintf(errmsg, errlen, "invalid block size: %d", enc->blocksize);
            return -1;
        }
    } else {
        enc->blocksize = select_blocksize(sample_rate, enc->block_time_ms);
    }
    enc->max_blocksize = enc->blocksize;

    enc->max_framesize = flacenc_max_frame_size(enc->blocksize, channels, enc->bps);
    enc->min_framesize = enc->max_framesize;
    enc->max_encoded_framesize = 0;

    /* allocate */
    for (int ch = 0; ch < channels; ch++) {
        enc->sub[ch].samples = calloc(enc->max_blocksize + 64, sizeof(int32_t));
        enc->sub[ch].residual = calloc(enc->max_blocksize + 64, sizeof(int32_t));
        enc->sub[ch].udata = calloc(enc->max_blocksize + 64, sizeof(uint32_t));
    }
    enc->windowed = calloc(enc->max_blocksize + 2 * FLAC_MAX_LPC_ORDER + 16, sizeof(double));
    enc->framebuf_cap = (size_t)enc->max_framesize * 2 + 4096;
