}

void flacenc_free(FlacEncoder *enc)
{
    for (int ch = 0; ch < enc->channels; ch++) {
        free(enc->sub[ch].samples); free(enc->sub[ch].residual); free(enc->sub[ch].udata);
    }
    free(enc->windowed);
    free(enc->framebuf);
}

void flacenc_write_streaminfo(FlacEncoder *enc, uint8_t out[34], int final)
