#include "wavio.h"

static uint8_t *read_all(FILE *f, size_t *len)
{
    size_t cap = 1 << 16, n = 0;
    uint8_t *buf = malloc(cap);
    for (;;) {
        if (n == cap) { cap *= 2; buf = realloc(buf, cap); }
        size_t r = fread(buf + n, 1, cap - n, f);
        if (r == 0) break;
        n += r;
    }
    *len = n;
    return buf;
}

int wav_read_file(const char *path, WavFile *w, char *err, size_t errlen)
{
    memset(w, 0, sizeof *w);
    FILE *f = strcmp(path, "-") == 0 ? stdin : fopen(path, "rb");
    if (!f) { snprintf(err, errlen, "cannot open"); return -1; }
    size_t len;
    uint8_t *buf = read_all(f, &len);
    if (f != stdin) fclose(f);
    if (len < 12 || memcmp(buf, "RIFF", 4) != 0 || memcmp(buf + 8, "WAVE", 4) != 0) {
        if (len >= 12 && memcmp(buf, "RF64", 4) == 0 && memcmp(buf + 8, "WAVE", 4) == 0) {
            w->ds64 = 1;
        } else {
            snprintf(err, errlen, "not a wav file"); free(buf); return -1;
        }
