#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include "log.h"

int log_level = LOG_INFO;
int log_flag_repeat = 0;
int log_flag_level = 0;

static char last_line[4096];
static int last_level = -1;
static int repeat_count = 0;
static int have_last = 0;

static const char *level_name(int level)
{
    if (level <= LOG_PANIC) return "panic";
    if (level <= LOG_FATAL) return "fatal";
    if (level <= LOG_ERROR) return "error";
    if (level <= LOG_WARNING) return "warning";
    if (level <= LOG_INFO) return "info";
    if (level <= LOG_VERBOSE) return "verbose";
    if (level <= LOG_DEBUG) return "debug";
    return "trace";
}

static void emit(int level, const char *line)
{
    if (log_flag_level)
        fprintf(stderr, "[%s] %s", level_name(level), line);
    else
        fputs(line, stderr);
}

static void output_line(int level, const char *line)
{
    if (level > log_level) return;
    if (!log_flag_repeat && have_last && strcmp(line, last_line) == 0 && level == last_level && line[0] != 0 && strchr(line, '\n')) {
        repeat_count++;
        return;
    }
    if (repeat_count > 0) {
        char buf[128];
        snprintf(buf, sizeof buf, "    Last message repeated %d times\n", repeat_count);
        emit(last_level, buf);
        repeat_count = 0;
    }
    emit(level, line);
    snprintf(last_line, sizeof last_line, "%s", line);
    last_level = level;
    have_last = 1;
    fflush(stderr);
}

void log_flush(void)
{
    if (repeat_count > 0) {
        char buf[128];
        snprintf(buf, sizeof buf, "    Last message repeated %d times\n", repeat_count);
        emit(last_level, buf);
        repeat_count = 0;
    }
    fflush(stderr);
}

void log_msg(int level, const char *fmt, ...)
{
    char buf[8192];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(buf, sizeof buf, fmt, ap);
    va_end(ap);
    output_line(level, buf);
}

void log_ctx(int level, const char *ctxname, const char *fmt, ...)
{
    char buf[8192];
    char msg[8000];
    va_list ap;
    va_start(ap, fmt);
    vsnprintf(msg, sizeof msg, fmt, ap);
    va_end(ap);
    snprintf(buf, sizeof buf, "[%s @ %s] %s", ctxname, fake_addr(ctxname), msg);
    output_line(level, buf);
}

/* produce a stable pseudo heap address for a context name */
const char *fake_addr(const char *key)
{
    static char bufs[8][32];
    static int idx = 0;
    static unsigned long base = 0;
    if (!base) {
        base = 0x55d000000000UL + ((unsigned long)(size_t)&base & 0xffffff000UL);
    }
    unsigned long h = 1469598103UL;
    for (const char *p = key; *p; p++) h = (h ^ (unsigned char)*p) * 1099511628211UL;
    unsigned long addr = base + ((h & 0xfffff) << 6);
    char *b = bufs[idx++ & 7];
    snprintf(b, 32, "0x%lx", addr);
    return b;
}

int log_parse_level(const char *arg)
{
    static const struct { const char *name; int level; } tab[] = {
        {"quiet", LOG_QUIET}, {"panic", LOG_PANIC}, {"fatal", LOG_FATAL}, {"error", LOG_ERROR},
        {"warning", LOG_WARNING}, {"info", LOG_INFO}, {"verbose", LOG_VERBOSE}, {"debug", LOG_DEBUG}, {"trace", LOG_TRACE}
    };
    const char *token = arg;
    char *tail;
    int flags = 0; /* bit0 repeat seen, bit1 level seen */
    /* flags: a sequence of [+-]flag or flag+ */
    for (;;) {
        int clear = 0;
        if (*token == '+' || *token == '-') { clear = *token == '-'; token++; }
        /* check for flag names followed by + or end */
        const char *names[] = {"repeat", "level", "time", "datetime", NULL};
        int matched = 0;
        for (int i = 0; names[i]; i++) {
            size_t l = strlen(names[i]);
            if (strncmp(token, names[i], l) == 0 && (token[l] == 0 || token[l] == '+')) {
                if (i == 0) log_flag_repeat = !clear;
                else if (i == 1) log_flag_level = !clear;
                token += l;
                if (*token == '+') token++;
                matched = 1;
                flags = 1;
                break;
            }
        }
        if (!matched) break;
        if (*token == 0) return 0;
    }
    for (size_t i = 0; i < sizeof tab / sizeof tab[0]; i++) {
        if (strcmp(token, tab[i].name) == 0) { log_level = tab[i].level; return 0; }
    }
    long v = strtol(token, &tail, 10);
    if (*token && !*tail) { log_level = (int)v; return 0; }
    (void)flags;
    fprintf(stderr, "Invalid loglevel \"%s\". Possible levels are numbers or:\n", arg);
    for (size_t i = 0; i < sizeof tab / sizeof tab[0]; i++) fprintf(stderr, "\"%s\"\n", tab[i].name);
    fprintf(stderr, "Possible flags are:\n\"repeat\"\n\"level\"\n\"time\"\n\"datetime\"\n");
    return -1;
}
