cat > src/dict.c <<'EOF'
#include <stdlib.h>
#include <string.h>
#include <strings.h>
#include "dict.h"

static int find(const Dict *d, const char *key)
{
    for (int i = 0; i < d->n; i++)
        if (strcasecmp(d->keys[i], key) == 0) return i;
    return -1;
}

void dict_del(Dict *d, const char *key)
{
    int i = find(d, key);
    if (i < 0) return;
    free(d->keys[i]); free(d->vals[i]);
    d->keys[i] = d->keys[d->n - 1];
    d->vals[i] = d->vals[d->n - 1];
    d->n--;
}

void dict_set(Dict *d, const char *key, const char *val)
{
    dict_del(d, key);
    if (!val) return;
    if (d->n == d->cap) {
        d->cap = d->cap ? d->cap * 2 : 8;
        d->keys = realloc(d->keys, d->cap * sizeof *d->keys);
        d->vals = realloc(d->vals, d->cap * sizeof *d->vals);
    }
    d->keys[d->n] = strdup(key);
    d->vals[d->n] = strdup(val);
    d->n++;
}

const char *dict_get(const Dict *d, const char *key)
{
    int i = find(d, key);
    return i < 0 ? NULL : d->vals[i];
}

void dict_copy(Dict *dst, const Dict *src)
{
    for (int i = 0; i < src->n; i++) dict_set(dst, src->keys[i], src->vals[i]);
}

void dict_free(Dict *d)
{
    for (int i = 0; i < d->n; i++) { free(d->keys[i]); free(d->vals[i]); }
    free(d->keys); free(d->vals);
    d->keys = d->vals = NULL; d->n = d->cap = 0;
}
