static const int sr_table[16] = { 0, 88200, 176400, 192000, 8000, 16000, 22050, 24000, 32000, 44100, 48000, 96000, 0, 0, 0, 0 };
static const int bs_table[16] = { 0, 192, 576, 1152, 2304, 4608, 0, 0, 256, 512, 1024, 2048, 4096, 8192, 16384, 32768 };
static const int bps_table[8] = { 0, 8, 12, 0, 16, 20, 24, 32 };

int flac_parse_streaminfo(const uint8_t *b, FlacStreamInfo *si)
{
    BitReader r; br_init(&r, b, 34);
    si->min_blocksize = br_get(&r, 16);
    si->max_blocksize = br_get(&r, 16);
    si->min_framesize = br_get(&r, 24);
    si->max_framesize = br_get(&r, 24);
    si->sample_rate = br_get(&r, 20);
    si->channels = br_get(&r, 3) + 1;
    si->bps = br_get(&r, 5) + 1;
    si->total_samples = br_get64(&r, 36);
    memcpy(si->md5, b + 18, 16);
    return 0;
}

int flac_parse_stream_header(const uint8_t *data, size_t len, FlacStreamInfo *si, Dict *meta, char **vendor, int *has_streaminfo)
{
    if (len < 4 || memcmp(data, "fLaC", 4) != 0) return -1;
    size_t p = 4;
    *has_streaminfo = 0;
    memset(si, 0, sizeof *si);
    for (;;) {
        if (p + 4 > len) return -1;
        int last = data[p] >> 7;
        int type = data[p] & 0x7f;
        uint32_t bl = rb24(data + p + 1);
        p += 4;
        if (p + bl > len) return -1;
        if (type == 0 && bl >= 34) {
            flac_parse_streaminfo(data + p, si);
            *has_streaminfo = 1;
        } else if (type == 4) {
            /* vorbis comment */
            const uint8_t *b = data + p; size_t q = 0;
            if (bl >= 4) {
                uint32_t vl = rl32(b); q = 4;
                if (q + vl <= bl) {
                    if (vendor) { *vendor = malloc(vl + 1); memcpy(*vendor, b + q, vl); (*vendor)[vl] = 0; }
                    q += vl;
                    if (q + 4 <= bl) {
                        uint32_t n = rl32(b + q); q += 4;
                        for (uint32_t i = 0; i < n && q + 4 <= bl; i++) {
                            uint32_t cl = rl32(b + q); q += 4;
                            if (q + cl > bl) break;
                            char *s = malloc(cl + 1); memcpy(s, b + q, cl); s[cl] = 0;
                            char *eq = strchr(s, '=');
                            if (eq && eq != s) {
                                *eq = 0;
                                const char *key = s;
                                /* standard key translation */
                                char keybuf[256];
                                if (strcasecmp(key, "ALBUMARTIST") == 0) key = "album_artist";
                                else if (strcasecmp(key, "TRACKNUMBER") == 0) key = "track";
                                else if (strcasecmp(key, "DISCNUMBER") == 0) key = "disc";
                                else if (strcasecmp(key, "DESCRIPTION") == 0) key = "comment";
                                else { snprintf(keybuf, sizeof keybuf, "%s", key); key = keybuf; }
                                /* append to existing value if same key present? ffmpeg: duplicate keys get appended with ';' */
                                const char *old = dict_get(meta, key);
                                if (old && (strcasecmp(key, "encoder") != 0)) {
                                    size_t l = strlen(old) + strlen(eq + 1) + 2;
                                    char *nv = malloc(l); snprintf(nv, l, "%s;%s", old, eq + 1);
                                    dict_set(meta, key, nv); free(nv);
                                } else
                                    dict_set(meta, key, eq + 1);
                            }
                            free(s);
                            q += cl;
                        }
                    }
                }
            }
        }
        p += bl;
        if (last) break;
    }
    return (int)p;
}

static int read_utf8(BitReader *r, int64_t *val)
{
    uint32_t b = br_get(r, 8);
    if (b < 0x80) { *val = b; return 1; }
    int n = 0;
    while (b & (0x80 >> n)) n++;
    if (n == 1 || n > 7) return -1;
    int64_t v = b & (0x7f >> n);
    for (int i = 1; i < n; i++) {
        uint32_t c = br_get(r, 8);
        if ((c & 0xc0) != 0x80) return -1;
        v = (v << 6) | (c & 0x3f);
    }
    *val = v;
    return n;
}

static int parse_header(BitReader *r, const uint8_t *data, const FlacStreamInfo *si, FlacFrameInfo *fi)
{
    if (br_get(r, 15) != 0x7ffc) return -1;
    fi->variable_blocksize = br_get1(r);
    int bs_code = br_get(r, 4);
    int sr_code = br_get(r, 4);
    int ch_code = br_get(r, 4);
    int bps_code = br_get(r, 3);
    if (br_get1(r) != 0) return -1;
    if (read_utf8(r, &fi->frame_number) < 0) return -1;
    if (bs_code == 0) return -1;
    else if (bs_code == 6) fi->blocksize = br_get(r, 8) + 1;
    else if (bs_code == 7) fi->blocksize = br_get(r, 16) + 1;
    else fi->blocksize = bs_table[bs_code];
    if (sr_code == 0) fi->sample_rate = si ? si->sample_rate : 0;
    else if (sr_code < 12) fi->sample_rate = sr_table[sr_code];
    else if (sr_code == 12) fi->sample_rate = br_get(r, 8) * 1000;
    else if (sr_code == 13) fi->sample_rate = br_get(r, 16);
    else if (sr_code == 14) fi->sample_rate = br_get(r, 16) * 10;
    else return -1;
    if (ch_code < 8) { fi->channels = ch_code + 1; fi->ch_mode = 0; }
    else if (ch_code < 11) { fi->channels = 2; fi->ch_mode = ch_code - 7; } /* 1: left/side 2: right/side 3: mid/side */
    else return -1;
    if (bps_code == 0) fi->bps = si ? si->bps : 0;
    else if (bps_code == 3) return -1;
    else fi->bps = bps_table[bps_code];
    br_align(r);
    size_t hdr_bytes = r->pos >> 3;
    uint8_t crc = br_get(r, 8);
    if (flac_crc8(data, hdr_bytes) != crc) return -1;
    return (int)(r->pos >> 3);
}

int flac_parse_frame_header(const uint8_t *data, size_t len, const FlacStreamInfo *si, FlacFrameInfo *fi)
{
    BitReader r; br_init(&r, data, len);
    if (len < 6) return -1;
    return parse_header(&r, data, si, fi);
}

static int decode_residuals(BitReader *r, int32_t *res, int blocksize, int pred_order)
{
    int method = br_get(r, 2);
    if (method > 1) return -1;
    int rice_bits = 4 + method;
    int rice_esc = (1 << rice_bits) - 1;
    int porder = br_get(r, 4);
    int psize = blocksize >> porder;
    if (pred_order > psize) return -1;
    int sample = pred_order;
    for (int p = 0; p < (1 << porder); p++) {
        int end = (p + 1) * psize;
        if (end > blocksize) end = blocksize;
        int k = br_get(r, rice_bits);
        if (k == rice_esc) {
            int bits = br_get(r, 5);
            for (; sample < end; sample++) res[sample] = bits ? br_get_signed(r, bits) : 0;
        } else {
            for (; sample < end; sample++) {
                uint32_t q = br_unary(r);
                uint32_t v = (q << k) | (k ? br_get(r, k) : 0);
                res[sample] = (int32_t)((v >> 1) ^ -(int32_t)(v & 1));
            }
        }
        if (br_bits_left(r) == 0 && sample < blocksize) return -1;
    }
    return 0;
}

static int decode_subframe(BitReader *r, int32_t *out, int blocksize, int bps)
{
    if (br_get1(r) != 0) return -1;
    int type = br_get(r, 6);
    int wasted = 0;
    if (br_get1(r)) {
        wasted = 1;
        while (br_get1(r) == 0) { wasted++; if (br_bits_left(r) == 0) return -1; }
    }
    bps -= wasted;
    if (bps > 32) return -1;
    if (type == 0) {
        int32_t v = br_get_signed(r, bps);
        for (int i = 0; i < blocksize; i++) out[i] = v;
    } else if (type == 1) {
        for (int i = 0; i < blocksize; i++) out[i] = br_get_signed(r, bps);
    } else if ((type & 0x38) == 0x08) {
        int order = type & 7;
        if (order > 4) return -1;
        for (int i = 0; i < order; i++) out[i] = br_get_signed(r, bps);
        if (decode_residuals(r, out, blocksize, order) < 0) return -1;
        switch (order) {
        case 0: break;
        case 1: for (int i = 1; i < blocksize; i++) out[i] += out[i - 1]; break;
        case 2: for (int i = 2; i < blocksize; i++) out[i] += 2 * out[i - 1] - out[i - 2]; break;
        case 3: for (int i = 3; i < blocksize; i++) out[i] += 3 * out[i - 1] - 3 * out[i - 2] + out[i - 3]; break;
        case 4: for (int i = 4; i < blocksize; i++) out[i] += 4 * out[i - 1] - 6 * out[i - 2] + 4 * out[i - 3] - out[i - 4]; break;
        }
    } else if (type >= 0x20) {
        int order = (type & 0x1f) + 1;
        for (int i = 0; i < order; i++) out[i] = br_get_signed(r, bps);
        int prec = br_get(r, 4) + 1;
        if (prec == 16) return -1;
        int shift = br_get_signed(r, 5);
        if (shift < 0) return -1;
        int32_t coefs[32];
        for (int i = 0; i < order; i++) coefs[i] = br_get_signed(r, prec);
        if (decode_residuals(r, out, blocksize, order) < 0) return -1;
        if (bps + prec + ilog2(order) <= 32) {
            for (int i = order; i < blocksize; i++) {
                int32_t sum = 0;
                for (int j = 0; j < order; j++) sum += coefs[j] * out[i - 1 - j];
                out[i] += sum >> shift;
            }
        } else {
            for (int i = order; i < blocksize; i++) {
                int64_t sum = 0;
                for (int j = 0; j < order; j++) sum += (int64_t)coefs[j] * out[i - 1 - j];
                out[i] += (int32_t)(sum >> shift);
            }
        }
    } else {
        return -1;
    }
    if (wasted) for (int i = 0; i < blocksize; i++) out[i] = (int32_t)((uint32_t)out[i] << wasted);
    return 0;
}

int flac_decode_frame(const uint8_t *data, size_t len, const FlacStreamInfo *si, int32_t *out, FlacFrameInfo *fi)
{
    BitReader r; br_init(&r, data, len);
    if (len < 6) return -1;
    if (parse_header(&r, data, si, fi) < 0) return -1;
    if (fi->blocksize <= 0 || fi->channels <= 0 || fi->bps <= 0) return -1;
    int32_t *ch[8];
    for (int c = 0; c < fi->channels; c++) {
        ch[c] = malloc(sizeof(int32_t) * fi->blocksize);
        int bps = fi->bps;
        if ((fi->ch_mode == 1 && c == 1) || (fi->ch_mode == 2 && c == 0) || (fi->ch_mode == 3 && c == 1)) bps++;
        if (decode_subframe(&r, ch[c], fi->blocksize, bps) < 0) {
            for (int k = 0; k <= c; k++) free(ch[k]);
            return -1;
        }
    }
    br_align(&r);
    size_t end = r.pos >> 3;
    if (end + 2 > len) { for (int c = 0; c < fi->channels; c++) free(ch[c]); return -1; }
    uint16_t crc = (uint16_t)br_get(&r, 16);
    if (flac_crc16(0, data, end) != crc) {
        /* ffmpeg logs a warning but still outputs; we behave the same */
    }
    /* channel decorrelation */
    int n = fi->blocksize;
    if (fi->ch_mode == 1) {
        for (int i = 0; i < n; i++) ch[1][i] = ch[0][i] - ch[1][i];
    } else if (fi->ch_mode == 2) {
        for (int i = 0; i < n; i++) ch[0][i] = ch[0][i] + ch[1][i];
    } else if (fi->ch_mode == 3) {
        for (int i = 0; i < n; i++) {
            int32_t mid = ch[0][i], side = ch[1][i];
            mid = (int32_t)(((uint32_t)mid << 1) | (side & 1));
            ch[0][i] = (mid + side) >> 1;
            ch[1][i] = (mid - side) >> 1;
        }
    }
    for (int i = 0; i < n; i++)
        for (int c = 0; c < fi->channels; c++)
            out[i * fi->channels + c] = ch[c][i];
    for (int c = 0; c < fi->channels; c++) free(ch[c]);
    return (int)(end + 2);
}
