        case 1: for (int i = 1; i < blocksize; i++) out[i] += out[i - 1]; break;
        case 2: for (int i = 2; i < blocksize; i++) out[i] += 2 * out[i - 1] - out[i - 2]; break;
        case 3: for (int i = 3; i < blocksize; i++) out[i] += 3 * out[i - 1] - 3 * out[i - 2] + out[i - 3]; break;
        case 4: for (int i = 4; i < blocksize; i++) out[i] += 4 * out[i - 1] - 6 * out[i - 2] + 4 * out[i - 3] - out[i - 4]; break;
        }
    } else if (type >= 0x20) {
        int order = (type & 0x1f) + 1;
        for (int i = 0; i < order; i++) out[i] = br_get_signed(r, bps);
        int prec = br_get(r, 4) + 1;
        if (prec == 16) return -1;
        int shift = br_get_signed(r, 5);
        if (shift < 0) return -1;
        int32_t coefs[32];
        for (int i = 0; i < order; i++) coefs[i] = br_get_signed(r, prec);
        if (decode_residuals(r, out, blocksize, order) < 0) return -1;
        if (bps + prec + ilog2(order) <= 32) {
            for (int i = order; i < blocksize; i++) {
                int32_t sum = 0;
                for (int j = 0; j < order; j++) sum += coefs[j] * out[i - 1 - j];
                out[i] += sum >> shift;
            }
        } else {
            for (int i = order; i < blocksize; i++) {
                int64_t sum = 0;
                for (int j = 0; j < order; j++) sum += (int64_t)coefs[j] * out[i - 1 - j];
                out[i] += (int32_t)(sum >> shift);
            }
        }
    } else {
        return -1;
    }
    if (wasted) for (int i = 0; i < blocksize; i++) out[i] = (int32_t)((uint32_t)out[i] << wasted);
    return 0;
}

int flac_decode_frame(const uint8_t *data, size_t len, const FlacStreamInfo *si, int32_t *out, FlacFrameInfo *fi)
{
    BitReader r; br_init(&r, data, len);
    if (len < 6) return -1;
    if (parse_header(&r, data, si, fi) < 0) return -1;
    if (fi->blocksize <= 0 || fi->channels <= 0 || fi->bps <= 0) return -1;
    int32_t *ch[8];
    for (int c = 0; c < fi->channels; c++) {
        ch[c] = malloc(sizeof(int32_t) * fi->blocksize);
        int bps = fi->bps;
        if ((fi->ch_mode == 1 && c == 1) || (fi->ch_mode == 2 && c == 0) || (fi->ch_mode == 3 && c == 1)) bps++;
        if (decode_subframe(&r, ch[c], fi->blocksize, bps) < 0) {
            for (int k = 0; k <= c; k++) free(ch[k]);
            return -1;
        }
    }
    br_align(&r);
    size_t end = r.pos >> 3;
    if (end + 2 > len) { for (int c = 0; c < fi->channels; c++) free(ch[c]); return -1; }
    uint16_t crc = (uint16_t)br_get(&r, 16);
    if (flac_crc16(0, data, end) != crc) {
        /* ffmpeg logs a warning but still outputs; we behave the same */
    }
    /* channel decorrelation */
    int n = fi->blocksize;
    if (fi->ch_mode == 1) {
        for (int i = 0; i < n; i++) ch[1][i] = ch[0][i] - ch[1][i];
    } else if (fi->ch_mode == 2) {
        for (int i = 0; i < n; i++) ch[0][i] = ch[0][i] + ch[1][i];
    } else if (fi->ch_mode == 3) {
        for (int i = 0; i < n; i++) {
            int32_t mid = ch[0][i], side = ch[1][i];
            mid = (int32_t)(((uint32_t)mid << 1) | (side & 1));
            ch[0][i] = (mid + side) >> 1;
            ch[1][i] = (mid - side) >> 1;
        }
    }
    for (int i = 0; i < n; i++)
        for (int c = 0; c < fi->channels; c++)
            out[i * fi->channels + c] = ch[c][i];
    for (int c = 0; c < fi->channels; c++) free(ch[c]);
    return (int)(end + 2);
}
