static int16_t sine_lookup(uint32_t idx)
{
    idx &= 32767;
    int sign = 1;
    if (idx >= 16384) { idx -= 16384; sign = -1; }
    if (idx > 8192) idx = 16384 - idx;
    return (int16_t)(sign * sine_quarter_table[idx]);
}

/* parse a duration like ffmpeg: [-][HH:]MM:SS[.m...] or [-]S+[.m...][s|ms|us] */
int parse_duration_us(const char *str, int64_t *out);

