{
    s->frequency = 440;
    s->beep_factor = 0;
    s->sample_rate = 44100;
    s->duration_us = 0;
    s->samples_per_frame = 1024;
    s->pts = 0;
    int positional = 0;
    const char *order[] = { "frequency", "beep_factor", "sample_rate", "duration", "samples_per_frame" };
    if (args && *args) {
        char *copy = strdup(args);
        char *save = copy;
        char *tok;
        while ((tok = strsep(&save, ":")) != NULL) {
            char *eq = strchr(tok, '=');
            const char *key; const char *val;
            if (eq) { *eq = 0; key = tok; val = eq + 1; }
            else {
                if (positional >= 5) { snprintf(err, errlen, "too many positional arguments"); free(copy); return -1; }
                key = order[positional++]; val = tok;
            }
            if (!strcmp(key, "frequency") || !strcmp(key, "f")) s->frequency = atof(val);
            else if (!strcmp(key, "beep_factor") || !strcmp(key, "b")) s->beep_factor = atof(val);
            else if (!strcmp(key, "sample_rate") || !strcmp(key, "r")) s->sample_rate = atoi(val);
            else if (!strcmp(key, "duration") || !strcmp(key, "d")) {
                if (parse_duration_us(val, &s->duration_us) < 0) { snprintf(err, errlen, "Unable to parse option value \"%s\" as duration", val); free(copy); return -1; }
            }
            else if (!strcmp(key, "samples_per_frame")) s->samples_per_frame = atoi(val);
            else { snprintf(err, errlen, "Option '%s' not found", key); free(copy); return -1; }
        }
        free(copy);
    }
    if (s->sample_rate < 1) { snprintf(err, errlen, "invalid sample rate"); return -1; }
    s->nb_samples_total = s->duration_us > 0 ? (int64_t)(s->duration_us * (int64_t)s->sample_rate / 1000000) : 0;
    s->dphi = ldexp(s->frequency, 32) / s->sample_rate;
    return 0;
}

int sine_next(SineSource *s, int16_t *out, int max)
{
    int n = s->samples_per_frame;
    if (n > max) n = max;
    if (s->nb_samples_total > 0) {
        if (s->pts >= s->nb_samples_total) return 0;
        if (s->pts + n > s->nb_samples_total) n = (int)(s->nb_samples_total - s->pts);
    }
    for (int i = 0; i < n; i++) {
        double ph = (double)(s->pts + i) * s->dphi + 0.5;
        uint32_t phi = (uint32_t)(uint64_t)ph;
        out[i] = sine_lookup(phi >> 17);
    }
    s->pts += n;
    return n;
}
