#include <ctype.h>
#include <errno.h>
#include "util.h"

static int is_digit(char c) { return c >= '0' && c <= '9'; }

int parse_duration_us(const char *str, int64_t *out)
{
    const char *p = str;
    int neg = 0;
    if (*p == '-') { neg = 1; p++; }
    if (!*p) return -1;
    int64_t secs = 0;
    int64_t us = 0;
    /* count colons */
    int colons = 0;
    for (const char *q = p; *q; q++) if (*q == ':') colons++;
    if (colons > 2) return -1;
    if (colons) {
        int64_t parts[3] = {0, 0, 0};
        int idx = 0;
        while (*p && *p != '.') {
            if (*p == ':') { idx++; p++; continue; }
            if (!is_digit(*p)) return -1;
            parts[idx] = parts[idx] * 10 + (*p - '0');
            p++;
        }
        if (colons == 2) secs = parts[0] * 3600 + parts[1] * 60 + parts[2];
        else secs = parts[0] * 60 + parts[1];
    } else {
        if (!is_digit(*p) && *p != '.') return -1;
        while (is_digit(*p)) { secs = secs * 10 + (*p - '0'); p++; }
    }
    if (*p == '.') {
        p++;
        int64_t mul = 100000;
        while (is_digit(*p)) { us += (*p - '0') * mul; mul /= 10; p++; }
    }
    int64_t total = secs * 1000000 + us;
    if (!colons) {
        if (!strcmp(p, "ms")) { total = secs * 1000 + us / 1000; p += 2; }
        else if (!strcmp(p, "us")) { total = secs + us / 1000000; p += 2; }
        else if (!strcmp(p, "s")) { p += 1; }
    }
    if (*p) return -1;
    *out = neg ? -total : total;
    return 0;
}

const char *err_text(int err)
{
    switch (err) {
    case ERR_EINVAL: return "Invalid argument";
    case ERR_ENOENT: return "No such file or directory";
    case ERR_EIO: return "Input/output error";
    case ERR_ENOMEM: return "Cannot allocate memory";
    case ERR_EPIPE: return "Broken pipe";
    case ERR_EEXIST: return "File exists";
    case ERR_EACCES: return "Permission denied";
    case -ENOTDIR: return "Not a directory";
    case -EISDIR: return "Is a directory";
    case ERR_INVALIDDATA: return "Invalid data found when processing input";
    case ERR_OPTION_NOT_FOUND: return "Option not found";
    case ERR_ENCODER_NOT_FOUND: return "Encoder not found";
    case ERR_DECODER_NOT_FOUND: return "Decoder not found";
    case ERR_MUXER_NOT_FOUND: return "Muxer not found";
    case ERR_DEMUXER_NOT_FOUND: return "Demuxer not found";
    case ERR_EXIT: return "Immediate exit requested";
    case ERR_EOF: return "End of file";
    case ERR_PATCHWELCOME: return "Not yet implemented in FFmpeg, patches welcome";
    case ERR_EXPERIMENTAL: return "Experimental feature";
    case ERR_STREAM_NOT_FOUND: return "Stream not found";
    case ERR_BUG: return "Internal bug, should not have happened";
    default: {
        static char buf[64];
        snprintf(buf, sizeof buf, "Error number %d occurred", err);
        return buf;
    }
    }
}

char *fmt_duration_hms(int64_t us, char *buf, size_t len)
{
    int64_t secs = us / 1000000;
    int64_t rem = us % 1000000;
    snprintf(buf, len, "%02d:%02d:%02d.%02d", (int)(secs / 3600), (int)((secs / 60) % 60), (int)(secs % 60), (int)((100 * rem) / 1000000));
    return buf;
}
