cd /workspace && cat > src/demux.c <<'EOF'
/* Input handling: probing, wav/flac/raw demuxing and decoding to PCM, lavfi sine. */
#include <errno.h>
#include <sys/stat.h>
#include "ffm.h"
#include "wavio.h"

static uint8_t *read_whole_file(const char *path, size_t *len, int *err)
{
    FILE *f;
    if (strcmp(path, "-") == 0 || strncmp(path, "pipe:", 5) == 0) f = stdin;
    else if (strncmp(path, "file:", 5) == 0) f = fopen(path + 5, "rb");
    else f = fopen(path, "rb");
    if (!f) { *err = -errno; return NULL; }
    struct stat stbuf;
    if (fstat(fileno(f), &stbuf) == 0 && S_ISDIR(stbuf.st_mode)) { if (f != stdin) fclose(f); *err = -EISDIR; return NULL; }
    size_t cap = 1 << 16, n = 0;
    uint8_t *buf = malloc(cap);
    for (;;) {
        if (n == cap) { cap *= 2; buf = realloc(buf, cap); }
        size_t r = fread(buf + n, 1, cap - n, f);
        if (r == 0) break;
        n += r;
    }
    if (f != stdin) fclose(f);
    *len = n;
    *err = 0;
    return buf;
}

static void add_packet(Input *in, int64_t pts, int nb_samples, const uint8_t *data, size_t size)
{
    in->pkts = realloc(in->pkts, sizeof(Packet) * (in->npkts + 1));
    Packet *p = &in->pkts[in->npkts++];
    p->pts = pts; p->nb_samples = nb_samples; p->size = size; p->flags = 1;
    p->data = malloc(size ? size : 1);
    memcpy(p->data, data, size);
}

static int wav_packet_samples(int sample_rate)
{
    int v = sample_rate / 10;
    int n = v > 0 ? 1 << ilog2((unsigned)v) : 1;
    return n < 1 ? 1 : n;
}

static const struct { const char *tag; const char *key; } riff_info_conv[] = {
    { "IPRD", "album" }, { "IART", "artist" }, { "ICMT", "comment" }, { "ICOP", "copyright" }, { "ICRD", "date" },
    { "IGNR", "genre" }, { "ILNG", "language" }, { "INAM", "title" }, { "IPRT", "track" }, { "ISFT", "encoder" }, { "ITCH", "encoded_by" },
};
const char *riff_tag_for_key(const char *key)
{
    for (size_t i = 0; i < ARRAY_ELEMS(riff_info_conv); i++) if (!strcasecmp(riff_info_conv[i].key, key)) return riff_info_conv[i].tag;
    return NULL;
}
static const char *riff_key_for_tag(const char *tag)
{
    for (size_t i = 0; i < ARRAY_ELEMS(riff_info_conv); i++) if (!strcmp(riff_info_conv[i].tag, tag)) return riff_info_conv[i].key;
    return NULL;
}

/* decode raw little-endian pcm bytes into the input's pcm buffer (native fmt representation) */
static void pcm_decode(Input *in, const uint8_t *data, size_t size)
{
    int bps = codec_bits(in->codec);
    int bytes = bps / 8;
    int64_t n = size / (bytes * in->channels) * in->channels;
    int fb = sample_fmt_bytes(in->sample_fmt);
    size_t old = (size_t)in->nb_samples * in->channels * fb;
    in->pcm = realloc(in->pcm, old + n * fb + 16);
    uint8_t *dst = in->pcm + old;
    for (int64_t i = 0; i < n; i++) {
        const uint8_t *p = data + i * bytes;
        switch (in->codec) {
        case CODEC_PCM_U8: dst[i] = p[0]; break;
        case CODEC_PCM_S8: dst[i] = (uint8_t)(p[0] + 128); break;
        case CODEC_PCM_S16LE: wl16(dst + 2 * i, rl16(p)); break;
        case CODEC_PCM_S16BE: wl16(dst + 2 * i, rb16(p)); break;
        case CODEC_PCM_S24LE: wl32(dst + 4 * i, rl24(p) << 8); break;
        case CODEC_PCM_S24BE: wl32(dst + 4 * i, rb24(p) << 8); break;
        case CODEC_PCM_S32LE: wl32(dst + 4 * i, rl32(p)); break;
        case CODEC_PCM_S32BE: wl32(dst + 4 * i, rb32(p)); break;
        case CODEC_PCM_F32LE: wl32(dst + 4 * i, rl32(p)); break;
        case CODEC_PCM_F64LE: wl64(dst + 8 * i, rl64(p)); break;
        case CODEC_PCM_ALAW: case CODEC_PCM_MULAW: {
            int v = p[0]; int16_t s;
            if (in->codec == CODEC_PCM_ALAW) {
                v ^= 0x55; int sign = v & 0x80; int exp = (v >> 4) & 7; int mant = v & 0x0f;
                int mag = exp == 0 ? (mant << 4) + 8 : ((mant << 4) + 0x108) << (exp - 1);
                s = (int16_t)(sign ? mag : -mag);
            } else {
                v = ~v; int sign = v & 0x80; int exp = (v >> 4) & 7; int mant = v & 0x0f;
                int mag = (((mant << 3) + 0x84) << exp) - 0x84;
                s = (int16_t)(sign ? -mag : mag);
            }
            wl16(dst + 2 * i, (uint16_t)s);
            break;
        }
        }
    }
    in->nb_samples += n / in->channels;
}

static int open_wav(Input *in, uint8_t *buf, size_t len)
{
    size_t pos = 12;
    int got_fmt = 0, got_data = 0;
    int ds64 = memcmp(buf, "RF64", 4) == 0;
    uint64_t ds64_data = 0;
    int fmt_tag = 0;
    size_t data_off = 0; uint64_t data_sz = 0;
    uint32_t channel_mask = 0; int valid_bits = 0;
    while (pos + 8 <= len) {
        const uint8_t *id = buf + pos;
        uint32_t sz = rl32(buf + pos + 4);
        size_t body = pos + 8;
        if (!memcmp(id, "fmt ", 4) && sz >= 14 && body + sz <= len) {
            fmt_tag = rl16(buf + body);
            in->channels = rl16(buf + body + 2);
            in->sample_rate = rl32(buf + body + 4);
            int byte_rate = rl32(buf + body + 8);
            in->block_align = rl16(buf + body + 12);
            int bits = sz >= 16 ? rl16(buf + body + 14) : 8;
            if (fmt_tag == 0xFFFE && sz >= 40) {
                valid_bits = rl16(buf + body + 18);
                channel_mask = rl32(buf + body + 20);
                fmt_tag = rl16(buf + body + 24);
            }
            in->bits_per_raw_sample = bits;
            if (fmt_tag == 1) {
                int bps = in->block_align * 8 / (in->channels ? in->channels : 1);
                if (bits == 8 || bps == 8) in->codec = CODEC_PCM_U8;
                else if (bps == 16) in->codec = CODEC_PCM_S16LE;
                else if (bps == 24) in->codec = CODEC_PCM_S24LE;
                else if (bps == 32) in->codec = CODEC_PCM_S32LE;
                else in->codec = CODEC_NONE;
                if (bits > 0 && bits < codec_bits(in->codec)) in->bits_per_raw_sample = bits;
                else in->bits_per_raw_sample = codec_bits(in->codec);
                if (in->codec == CODEC_PCM_S24LE && bits == 24) in->bits_per_raw_sample = 24;
            } else if (fmt_tag == 3) {
                in->codec = bits == 64 ? CODEC_PCM_F64LE : CODEC_PCM_F32LE;
            } else if (fmt_tag == 6) in->codec = CODEC_PCM_ALAW;
            else if (fmt_tag == 7) in->codec = CODEC_PCM_MULAW;
            else if (fmt_tag == 0xF1AC) in->codec = CODEC_FLAC;
            else in->codec = CODEC_NONE;
            in->bit_rate = (int64_t)byte_rate * 8;
            (void)valid_bits;
            got_fmt = 1;
        } else if (!memcmp(id, "ds64", 4) && body + 28 <= len) {
            ds64_data = rl64(buf + body + 8);
        } else if (!memcmp(id, "data", 4)) {
            if (!got_fmt) { return ERR_INVALIDDATA; }
            got_data = 1;
            data_off = body;
            data_sz = sz;
            if (sz == 0xFFFFFFFFu && ds64) data_sz = ds64_data;
            if (sz == 0xFFFFFFFFu || body + data_sz > len) { data_sz = len - body; in->ignore_length = 1; }
            if (in->ignore_length) data_sz = len - body;
            sz = (uint32_t)data_sz;
            if (body + data_sz >= len) { pos = len; break; }
        } else if (!memcmp(id, "LIST", 4) && sz >= 4 && body + 4 <= len && !memcmp(buf + body, "INFO", 4)) {
            size_t p = body + 4, end = body + sz; if (end > len) end = len;
            while (p + 8 <= end) {
                uint32_t isz = rl32(buf + p + 4);
                if (p + 8 + isz > end) break;
                char tag[5]; memcpy(tag, buf + p, 4); tag[4] = 0;
                size_t vl = isz;
                while (vl > 0 && buf[p + 8 + vl - 1] == 0) vl--;
                char *val = malloc(vl + 1); memcpy(val, buf + p + 8, vl); val[vl] = 0;
                const char *key = riff_key_for_tag(tag);
                if (vl > 0 && isz > 0) dict_set(&in->metadata, key ? key : tag, val);
                free(val);
                p += 8 + isz + (isz & 1);
            }
        }
        pos = body + sz + (sz & 1);
    }
    if (!got_fmt) return ERR_INVALIDDATA;
    if (!got_data) return ERR_INVALIDDATA;
    if (in->channels <= 0 || in->sample_rate <= 0) return ERR_INVALIDDATA;
    if (in->codec == CODEC_NONE) return ERR_INVALIDDATA;
    if (in->block_align <= 0) in->block_align = in->channels * codec_bits(in->codec) / 8;
    in->sample_fmt = codec_sample_fmt(in->codec);
    if (in->codec == CODEC_PCM_S24LE) in->bits_per_raw_sample = 24;
    else if (in->codec != CODEC_FLAC) in->bits_per_raw_sample = codec_bits(in->codec);
    in->layout_guessed = (channel_mask == 0);
    in->fmt_name = "wav";
    in->fmt_long_name = "WAV / WAVE (Waveform Audio)";
    /* packets */
    int per = wav_packet_samples(in->sample_rate);
    size_t pkt_bytes = (size_t)per * in->block_align;
    int64_t pts = 0;
    uint64_t total_frames = data_sz / in->block_align;
    for (uint64_t off = 0; off + in->block_align <= data_sz; ) {
        size_t chunk = pkt_bytes;
        if (off + chunk > data_sz) chunk = (size_t)((data_sz - off) / in->block_align * in->block_align);
        add_packet(in, pts, (int)(chunk / in->block_align), buf + data_off + off, chunk);
        pts += chunk / in->block_align;
        off += chunk;
    }
    if (in->codec != CODEC_FLAC)
        pcm_decode(in, buf + data_off, (size_t)(total_frames * in->block_align));
    in->duration_us = (int64_t)((total_frames * 1000000 + in->sample_rate / 2) / in->sample_rate);
    /* ffmpeg: duration rescaled with rounding to nearest */
    {
        long double d = (long double)total_frames * 1000000.0L / in->sample_rate;
        in->duration_us = (int64_t)(d + 0.5L);
    }
    in->start_time_us = -1;
    return 0;
}

static int open_flac(Input *in, uint8_t *buf, size_t len)
{
    FlacStreamInfo si; char *vendor = NULL; int has_si = 0;
    int off = flac_parse_stream_header(buf, len, &si, &in->metadata, &vendor, &has_si);
    free(vendor);
    if (off < 0 || !has_si) return ERR_INVALIDDATA;
    in->si = si;
    memcpy(in->flac_streaminfo, buf + 8, 34); /* streaminfo must be first block */
    /* find the STREAMINFO block bytes exactly */
    {
        size_t p = 4;
        while (p + 4 <= len) {
            int last = buf[p] >> 7, type = buf[p] & 0x7f; uint32_t bl = rb24(buf + p + 1);
            if (type == 0 && bl >= 34) { memcpy(in->flac_streaminfo, buf + p + 4, 34); break; }
            p += 4 + bl;
            if (last) break;
        }
    }
    in->has_flac_streaminfo = 1;
    in->codec = CODEC_FLAC;
    in->sample_rate = si.sample_rate;
    in->channels = si.channels;
    in->bits_per_raw_sample = si.bps;
    in->sample_fmt = si.bps > 16 ? FMT_S32 : FMT_S16;
    in->block_align = 0;
    in->bit_rate = 0;
    in->fmt_name = "flac";
    in->fmt_long_name = "raw FLAC";
    in->flac_total_known = si.total_samples > 0;
    /* decode frames */
    size_t p = off;
    int64_t pts = 0;
    int32_t *tmp = malloc(sizeof(int32_t) * 65536 * 8);
    int fb = sample_fmt_bytes(in->sample_fmt);
    int shift = (in->sample_fmt == FMT_S32 ? 32 : 16) - si.bps;
    while (p + 2 <= len) {
        /* find sync */
        if (!(buf[p] == 0xFF && (buf[p + 1] & 0xFE) == 0xF8)) { p++; continue; }
        FlacFrameInfo fi;
        int consumed = flac_decode_frame(buf + p, len - p, &si, tmp, &fi);
        if (consumed < 0) { p++; continue; }
        add_packet(in, pts, fi.blocksize, buf + p, consumed);
        size_t old = (size_t)in->nb_samples * in->channels * fb;
        size_t add = (size_t)fi.blocksize * fi.channels * fb;
        in->pcm = realloc(in->pcm, old + add + 16);
        for (int i = 0; i < fi.blocksize * fi.channels; i++) {
            int32_t v = (int32_t)((uint32_t)tmp[i] << shift);
            if (fb == 2) wl16(in->pcm + old + 2 * i, (uint16_t)v);
            else wl32(in->pcm + old + 4 * i, (uint32_t)v);
        }
        in->nb_samples += fi.blocksize;
        pts += fi.blocksize;
        p += consumed;
    }
    free(tmp);
    if (si.total_samples > 0) {
        long double d = (long double)si.total_samples * 1000000.0L / in->sample_rate;
        in->duration_us = (int64_t)(d + 0.5L);
    } else in->duration_us = -1;
    in->start_time_us = in->npkts > 1 ? 0 : -1;
    return 0;
}

static int open_raw(Input *in, uint8_t *buf, size_t len, int codec)
{
    in->codec = codec;
    in->sample_rate = in->opt_ar > 0 ? in->opt_ar : 44100;
    in->channels = in->opt_ac > 0 ? in->opt_ac : 1;
    in->bits_per_raw_sample = codec_bits(codec);
    in->sample_fmt = codec_sample_fmt(codec);
    in->block_align = in->channels * codec_bits(codec) / 8;
    in->bit_rate = (int64_t)in->sample_rate * in->block_align * 8;
    in->fmt_name = codec_name(codec) + 4;
    in->layout_guessed = 1;
    /* raw pcm demuxer: packets of max(sample_rate/25,1) samples, clamped to 1024 */
    int per = in->sample_rate / 25; if (per < 1) per = 1; if (per > 1024) per = 1024;
    size_t pkt_bytes = (size_t)per * in->block_align;
    int64_t pts = 0;
    size_t total = len / in->block_align * in->block_align;
    for (size_t off = 0; off < total; ) {
        size_t chunk = MIN(pkt_bytes, total - off);
        add_packet(in, pts, (int)(chunk / in->block_align), buf + off, chunk);
        pts += chunk / in->block_align; off += chunk;
    }
    pcm_decode(in, buf, total);
    long double d = (long double)(total / in->block_align) * 1000000.0L / in->sample_rate;
    in->duration_us = (int64_t)(d + 0.5L);
    in->start_time_us = 0;
    return 0;
}

static int open_lavfi(Input *in)
{
    /* graph: "sine=..." possibly with [out0] label and ';' separators; only sine supported */
    char *desc = strdup(in->url);
    char *g = desc;
    while (*g == ' ') g++;
    /* strip output pad labels like [out0] */
    char *name_end = g;
    while (*name_end && *name_end != '=' && *name_end != '[' && *name_end != ',' && *name_end != ';' && *name_end != '@') name_end++;
    char fname[64]; size_t fl = MIN((size_t)(name_end - g), sizeof fname - 1);
    memcpy(fname, g, fl); fname[fl] = 0;
    const char *args = "";
    char *argbuf = NULL;
    if (*name_end == '@') { while (*name_end && *name_end != '=' && *name_end != '[') name_end++; }
    if (*name_end == '=') {
        char *a = name_end + 1;
        char *e = a;
        while (*e && *e != '[' && *e != ';' && *e != ',') e++;
        argbuf = malloc(e - a + 1); memcpy(argbuf, a, e - a); argbuf[e - a] = 0;
        args = argbuf;
    }
    if (strcmp(fname, "sine") != 0) {
        log_ctx(LOG_ERROR, "AVFilterGraph", "No such filter: '%s'\n", fname);
        free(desc); free(argbuf);
        return ERR_EINVAL;
    }
    char err[256];
    if (sine_init(&in->sine, args, err, sizeof err) < 0) {
        log_ctx(LOG_ERROR, "Parsed_sine_0", "%s\n", err);
        free(desc); free(argbuf);
        return ERR_EINVAL;
    }
    free(desc); free(argbuf);
    in->is_lavfi = 1;
    in->codec = CODEC_PCM_S16LE;
    in->sample_rate = in->sine.sample_rate;
    in->channels = 1;
    in->bits_per_raw_sample = 16;
    in->sample_fmt = FMT_S16;
    in->block_align = 2;
    in->bit_rate = (int64_t)in->sample_rate * 16;
    in->fmt_name = "lavfi";
    in->fmt_long_name = "Libavfilter virtual input device";
    in->duration_us = -1;
    in->start_time_us = 0;
    in->layout_guessed = 0;
    return 0;
}

/* generate lavfi samples (bounded by -t if given, otherwise by the duration option) */
int lavfi_generate(Input *in, int64_t max_samples)
{
    int16_t tmp[65536];
    int64_t pts = 0;
    for (;;) {
        int want = in->sine.samples_per_frame;
        if (max_samples >= 0 && pts + want > max_samples) want = (int)(max_samples - pts);
        if (want <= 0) break;
        int n = sine_next(&in->sine, tmp, want);
        if (n <= 0) break;
        size_t old = (size_t)in->nb_samples * 2;
        in->pcm = realloc(in->pcm, old + n * 2 + 16);
        for (int i = 0; i < n; i++) wl16(in->pcm + old + 2 * i, (uint16_t)tmp[i]);
        add_packet(in, pts, n, in->pcm + old, n * 2);
        in->nb_samples += n;
        pts += n;
        if (n < in->sine.samples_per_frame) { /* partial = last */ }
    }
    return 0;
}

int input_open(Input *in)
{
    char ctx[64];
    snprintf(ctx, sizeof ctx, "in#%d", in->index);
    if (in->opt_format && !strcmp(in->opt_format, "lavfi")) {
        int r = open_lavfi(in);
        if (r < 0) {
            log_ctx(LOG_ERROR, ctx, "Error opening input: %s\n", err_text(r));
            return r;
        }
        return 0;
    }
    if (in->opt_format) {
        static const char *known[] = { "wav", "flac", "s16le", "s24le", "s32le", "u8", "s8", "f32le", "f64le", "s16be", "s24be", "s32be", "alaw", "mulaw", "lavfi", NULL };
        int ok = 0;
        for (int i = 0; known[i]; i++) if (!strcmp(known[i], in->opt_format)) ok = 1;
        if (!ok) {
            log_ctx(LOG_ERROR, ctx, "Unknown input format: '%s'\n", in->opt_format);
            return ERR_DEMUXER_NOT_FOUND;
        }
    }
    size_t len = 0; int err = 0;
    uint8_t *buf = read_whole_file(in->url, &len, &err);
    if (!buf) {
        log_ctx(LOG_ERROR, ctx, "Error opening input: %s\n", err_text(err));
        return err;
    }
    struct stat stbuf;
    in->file_size = (int64_t)len;
    (void)stbuf;
    int r;
    const char *f = in->opt_format;
    if (f && !strcmp(f, "wav")) {
        if (len < 12 || (memcmp(buf, "RIFF", 4) && memcmp(buf, "RF64", 4)) || memcmp(buf + 8, "WAVE", 4)) r = ERR_INVALIDDATA;
        else r = open_wav(in, buf, len);
    } else if (f && !strcmp(f, "flac")) {
        r = open_flac(in, buf, len);
    } else if (f) {
        int codec = CODEC_NONE;
        if (!strcmp(f, "s16le")) codec = CODEC_PCM_S16LE; else if (!strcmp(f, "s24le")) codec = CODEC_PCM_S24LE;
        else if (!strcmp(f, "s32le")) codec = CODEC_PCM_S32LE; else if (!strcmp(f, "u8")) codec = CODEC_PCM_U8;
        else if (!strcmp(f, "s8")) codec = CODEC_PCM_S8; else if (!strcmp(f, "f32le")) codec = CODEC_PCM_F32LE;
        else if (!strcmp(f, "f64le")) codec = CODEC_PCM_F64LE; else if (!strcmp(f, "s16be")) codec = CODEC_PCM_S16BE;
        else if (!strcmp(f, "s24be")) codec = CODEC_PCM_S24BE; else if (!strcmp(f, "s32be")) codec = CODEC_PCM_S32BE;
        else if (!strcmp(f, "alaw")) codec = CODEC_PCM_ALAW; else if (!strcmp(f, "mulaw")) codec = CODEC_PCM_MULAW;
        r = open_raw(in, buf, len, codec);
    } else if (len >= 12 && (!memcmp(buf, "RIFF", 4) || !memcmp(buf, "RF64", 4)) && !memcmp(buf + 8, "WAVE", 4)) {
        r = open_wav(in, buf, len);
    } else if (len >= 4 && !memcmp(buf, "fLaC", 4)) {
        r = open_flac(in, buf, len);
    } else {
        r = ERR_INVALIDDATA;
    }
    free(buf);
    if (r < 0) {
        log_ctx(LOG_ERROR, ctx, "Error opening input: %s\n", err_text(r));
        return r;
    }
    if (in->duration_us >= 0 && in->file_size > 0 && in->duration_us > 0)
        in->fmt_bit_rate = (int64_t)((long double)in->file_size * 8 * 1000000.0L / in->duration_us);
    else in->fmt_bit_rate = 0;
    return 0;
}
