{"command":"cd /workspace && cat > src/mux.c <<'EOF'
/* Output muxers: wav, flac, raw pcm, md5/hash/framemd5/framecrc/crc/null */
#include "ffm.h"
#include "crc.h"

const char *riff_tag_for_key(const char *key);

#define LAVF_IDENT "Lavf62.9.101"

typedef struct {
    MD5Ctx md5; SHA256Ctx sha; SHA1Ctx sha1; uint32_t crc; int kind; /* 0 md5, 1 sha256, 2 sha224, 3 sha160, 4 crc32, 5 adler32 */
} HashState;

static HashState g_hash;
static int g_hash_inited;

static int hash_kind(const char *name)
{
    if (!name || !strcasecmp(name, "md5")) return 0;
    if (!strcasecmp(name, "sha256")) return 1;
    if (!strcasecmp(name, "sha224")) return 2;
    if (!strcasecmp(name, "sha160")) return 3;
    if (!strcasecmp(name, "crc32")) return 4;
    if (!strcasecmp(name, "adler32")) return 5;
    return -1;
}
static const char *hash_name(int kind)
{
    static const char *n[] = { "MD5", "SHA256", "SHA224", "SHA160", "CRC32", "adler32" };
    return n[kind];
}
static void hash_init(HashState *h, int kind)
{
    h->kind = kind;
    md5_init(&h->md5); sha256_init(&h->sha, kind == 2 ? 224 : 256); sha1_init(&h->sha1);
    h->crc = kind == 5 ? 1 : 0;
}
static void hash_update(HashState *h, const uint8_t *d, size_t n)
{
    switch (h->kind) {
    case 0: md5_update(&h->md5, d, n); break;
    case 1: case 2: sha256_update(&h->sha, d, n); break;
    case 3: sha1_update(&h->sha1, d, n); break;
    case 4: h->crc = crc32_ieee_le(h->crc, d, n); break;
    case 5: h->crc = adler32_update(h->crc, d, n); break;
    }
}
static void hash_final_hex(HashState *h, char *out)
{
    uint8_t buf[32]; int len = 16;
    switch (h->kind) {
    case 0: md5_final(&h->md5, buf); len = 16; break;
    case 1: sha256_final(&h->sha, buf); len = 32; break;
    case 2: sha256_final(&h->sha, buf); len = 28; break;
    case 3: sha1_final(&h->sha1, buf); len = 20; break;
    case 4: case 5: wb32(buf, h->crc); len = 4; break;
    }
    for (int i = 0; i < len; i++) sprintf(out + 2 * i, "%02x", buf[i]);
    out[2 * len] = 0;
}

static int is_wav_extensible(OutStream *st)
{
    return st->channels > 2 || st->sample_rate > 48000 || codec_bits(st->codec) > 16 || st->bits_per_raw_sample > 16;
}

static void write_wav_header(Output *o)
{
    OutStream *st = &o->st;
    ByteBuf *b = &o->buf;
    int ext = is_wav_extensible(st);
    int bits = codec_bits(st->codec);
    int block_align = st->channels * bits / 8;
    bb_put(b, o->wav_rf64 == 1 ? "RF64" : "RIFF", 4);
    bb_wl32(b, o->wav_rf64 == 1 ? 0xFFFFFFFFu : (o->is_pipe ? 0xFFFFFFFFu : 0));
    bb_put(b, "WAVE", 4);
    if (o->wav_rf64 == 1) {
        bb_put(b, "ds64", 4); bb_wl32(b, 28);
        for (int i = 0; i < 28; i++) bb_putc(b, 0);
    }
    bb_put(b, "fmt ", 4);
    bb_wl32(b, ext ? 40 : 16);
    bb_wl16(b, ext ? 0xFFFE : codec_wav_tag(st->codec));
    bb_wl16(b, st->channels);
    bb_wl32(b, st->sample_rate);
    bb_wl32(b, (uint32_t)st->sample_rate * block_align);
    bb_wl16(b, block_align);
    bb_wl16(b, bits);
    if (ext) {
        bb_wl16(b, 22);
        bb_wl16(b, bits);
        uint32_t mask = st->channels == 1 ? 4 : st->channels == 2 ? 3 : st->channels == 3 ? 0x7 : st->channels == 4 ? 0x33 : st->channels == 5 ? 0x37 : st->channels == 6 ? 0x3f : st->channels == 7 ? 0x13f : st->channels == 8 ? 0x63f : 0;
        bb_wl32(b, mask);
        bb_wl16(b, codec_wav_tag(st->codec));
        static const uint8_t guid_rest[14] = { 0x00, 0x00, 0x00, 0x00, 0x10, 0x00, 0x80, 0x00, 0x00, 0xAA, 0x00, 0x38, 0x9B, 0x71 };
        bb_put(b, guid_rest, 14);
    }
    /* LIST INFO */
    {
        static const char riff_tags[][5] = { "IARL", "IART", "ICMS", "ICMT", "ICOP", "ICRD", "ICRP", "IDIM", "IDPI", "IENG", "IGNR", "IKEY", "ILGT", "ILNG", "IMED", "INAM", "IPLT", "IPRD", "IPRT", "ISBJ", "ISFT", "ISHP", "ISRC", "ISRF", "ITCH" };
        ByteBuf info = {0};
        for (size_t i = 0; i < ARRAY_ELEMS(riff_tags); i++) {
            const char *v = dict_get(&o->metadata, riff_tags[i]);
            if (!v) continue;
            size_t l = strlen(v) + 1;
            bb_put(&info, riff_tags[i], 4);
            bb_wl32(&info, (uint32_t)l);
            bb_put(&info, v, l);
            if (l & 1) bb_putc(&info, 0);
        }
        if (info.len) {
            bb_put(b, "LIST", 4);
            bb_wl32(b, (uint32_t)(4 + info.len));
            bb_put(b, "INFO", 4);
            bb_put(b, info.data, info.len);
        }
        bb_free(&info);
    }
    bb_put(b, "data", 4);
    bb_wl32(b, o->is_pipe ? 0xFFFFFFFFu : 0);
}

static void write_flac_vorbis_comment(Output *o, ByteBuf *b, int last)
{
    ByteBuf vc = {0};
    const char *vendor = o->bitexact ? "ffmpeg" : LAVF_IDENT;
    bb_wl32(&vc, (uint32_t)strlen(vendor)); bb_put(&vc, vendor, strlen(vendor));
    bb_wl32(&vc, (uint32_t)o->metadata.n);
    for (int i = 0; i < o->metadata.n; i++) {
        size_t kl = strlen(o->metadata.keys[i]), vl = strlen(o->metadata.vals[i]);
        bb_wl32(&vc, (uint32_t)(kl + 1 + vl));
        bb_put(&vc, o->metadata.keys[i], kl); bb_putc(&vc, '='); bb_put(&vc, o->metadata.vals[i], vl);
    }
    bb_putc(b, (last ? 0x80 : 0) | 4);
    bb_wb24(b, (uint32_t)vc.len);
    bb_put(b, vc.data, vc.len);
    bb_free(&vc);
}

static void write_flac_header(Output *o, const uint8_t *streaminfo)
{
    ByteBuf *b = &o->buf;
    bb_put(b, "fLaC", 4);
    bb_putc(b, 0); bb_wb24(b, 34);
    bb_put(b, streaminfo, 34);
    write_flac_vorbis_comment(o, b, 0);
    /* padding */
    bb_putc(b, 0x81); bb_wb24(b, 8192);
    for (int i = 0; i < 8192; i++) bb_putc(b, 0);
}

int mux_write_header(Output *o, const uint8_t *flac_streaminfo)
{
    OutStream *st = &o->st;
    const char *f = o->fmt_name;
    if (!strcmp(f, "wav")) {
        write_wav_header(o);
    } else if (!strcmp(f, "flac")) {
        if (o->write_header) write_flac_header(o, flac_streaminfo);
    } else if (!strcmp(f, "framecrc") || !strcmp(f, "framemd5")) {
        char line[512];
        if (!strcmp(f, "framemd5")) {
            int k = hash_kind(o->hash_algo);
            snprintf(line, sizeof line, "#format: frame checksums\n#version: 2\n#hash: %s\n", hash_name(k));
            bb_put(&o->buf, line, strlen(line));
        }
        if (!o->bitexact) { snprintf(line, sizeof line, "#software: %s\n", LAVF_IDENT); bb_put(&o->buf, line, strlen(line)); }
        if (st->codec == CODEC_FLAC && o->st.copy == 0) {
            /* extradata line written after header: handled by caller via mux_write_extradata */
        }
        char lay[64];
        snprintf(line, sizeof line, "#tb 0: 1/%d\n#media_type 0: audio\n#codec_id 0: %s\n#sample_rate 0: %d\n#channel_layout_name 0: %s\n",
                 st->sample_rate, codec_name(st->codec), st->sample_rate, channel_layout_name(st->channels, lay, sizeof lay));
        bb_put(&o->buf, line, strlen(line));
        if (!strcmp(f, "framemd5")) {
            const char *h = "#stream#, dts,        pts, duration,     size, hash\n";
