    } else if (!strcmp(f, "md5") || !strcmp(f, "hash")) {
        int k = hash_kind(o->hash_algo);
        if (k < 0) return ERR_EINVAL;
        hash_init(&g_hash, k); g_hash_inited = 1;
    } else if (!strcmp(f, "crc")) {
        hash_init(&g_hash, 5); g_hash_inited = 1;
    }
