static const OptDef *find_opt(const char *name, char *spec, size_t speclen)
{
    /* strip :spec */
    const char *colon = strchr(name, ':');
    char base[128];
    size_t bl = colon ? (size_t)(colon - name) : strlen(name);
    if (bl >= sizeof base) return NULL;
    memcpy(base, name, bl); base[bl] = 0;
    if (spec) { if (colon) snprintf(spec, speclen, "%s", colon + 1); else spec[0] = 0; }
    for (size_t i = 0; i < ARRAY_ELEMS(optdefs); i++)
        if (!strcmp(optdefs[i].name, base)) {
            if (colon && !(optdefs[i].flags & (OPT_SPEC | OPT_AVOPT))) return NULL;
            return &optdefs[i];
        }
    return NULL;
}

/* collected options for one file */
typedef struct {
    char **names; char **vals; char **specs; int n;
} OptList;
static void optlist_add(OptList *l, const char *name, const char *spec, const char *val)
{
    l->names = realloc(l->names, sizeof(char *) * (l->n + 1));
    l->vals = realloc(l->vals, sizeof(char *) * (l->n + 1));
    l->specs = realloc(l->specs, sizeof(char *) * (l->n + 1));
    l->names[l->n] = strdup(name); l->vals[l->n] = val ? strdup(val) : NULL; l->specs[l->n] = strdup(spec ? spec : "");
    l->n++;
}
static const char *optlist_get(OptList *l, const char *name)
{
    const char *r = NULL;
    for (int i = 0; i < l->n; i++) if (!strcmp(l->names[i], name)) r = l->vals[i];
    return r;
}
static int optlist_has(OptList *l, const char *name)
{
    for (int i = 0; i < l->n; i++) if (!strcmp(l->names[i], name)) return 1;
    return 0;
}

typedef struct { char *url; OptList opts; int is_input; } FileSpec;
