static const OptDef *find_opt(const char *name, char *spec, size_t speclen)
{
    /* strip :spec */
    const char *colon = strchr(name, ':');
    char base[128];
    size_t bl = colon ? (size_t)(colon - name) : strlen(name);
    if (bl >= sizeof base) return NULL;
    memcpy(base, name, bl); base[bl] = 0;
    if (spec) { if (colon) snprintf(spec, speclen, "%s", colon + 1); else spec[0] = 0; }
    for (size_t i = 0; i < ARRAY_ELEMS(optdefs); i++)
        if (!strcmp(optdefs[i].name, base)) {
            if (colon && !(optdefs[i].flags & (OPT_SPEC | OPT_AVOPT))) return NULL;
            return &optdefs[i];
        }
    return NULL;
}

/* collected options for one file */
typedef struct {
    char **names; char **vals; char **specs; int n;
} OptList;
static void optlist_add(OptList *l, const char *name, const char *spec, const char *val)
{
    l->names = realloc(l->names, sizeof(char *) * (l->n + 1));
    l->vals = realloc(l->vals, sizeof(char *) * (l->n + 1));
    l->specs = realloc(l->specs, sizeof(char *) * (l->n + 1));
    l->names[l->n] = strdup(name); l->vals[l->n] = val ? strdup(val) : NULL; l->specs[l->n] = strdup(spec ? spec : "");
    l->n++;
}
static const char *optlist_get(OptList *l, const char *name)
{
    const char *r = NULL;
    for (int i = 0; i < l->n; i++) if (!strcmp(l->names[i], name)) r = l->vals[i];
    return r;
}
static int optlist_has(OptList *l, const char *name)
{
    for (int i = 0; i < l->n; i++) if (!strcmp(l->names[i], name)) return 1;
    return 0;
}

typedef struct { char *url; OptList opts; int is_input; } FileSpec;
static FileSpec *infiles; static int ninfiles;
static FileSpec *outfiles; static int noutfiles;
static OptList global_opts;

static int parse_int_opt(const char *name, const char *val, int *out)
{
    char *end; long v = strtol(val, &end, 0);
    if (*val && !*end) { *out = (int)v; return 0; }
    /* named constants handled by caller */
    return -1;
}

static int spec_matches_audio(const char *spec)
{
    /* stream specifier: "", "a", "a:0", "0", "0:0"?, "a:0" */
    if (!spec || !*spec) return 1;
    if (!strcmp(spec, "a") || !strncmp(spec, "a:", 2)) return 1;
    if (!strcmp(spec, "0")) return 1;
    if (!strcmp(spec, "v") || !strncmp(spec, "v:", 2) || !strcmp(spec, "s") || !strncmp(spec, "s:", 2) || !strcmp(spec, "d") || !strncmp(spec, "d:", 2)) return 0;
    return 1;
}

/* ---------------- dumps ---------------- */
static void dump_metadata(const Dict *d, const char *indent)
{
    if (!d->n) return;
    log_msg(LOG_INFO, "%sMetadata:\n", indent);
    for (int i = 0; i < d->n; i++) {
        /* ffmpeg prints key padded to 16, value with newlines replaced */
        char val[4096]; size_t j = 0;
        for (const char *p = d->vals[i]; *p && j < sizeof val - 2; p++) {
            if (*p == '\n') { val[j++] = '\n'; } else val[j++] = *p;
        }
        val[j] = 0;
        log_msg(LOG_INFO, "%s  %-16s: %s\n", indent, d->keys[i], val);
    }
}

static void fmt_bitrate_kb(int64_t br, char *buf, size_t len)
{
    snprintf(buf, len, "%" PRId64 " kb/s", br / 1000);
}

static void stream_desc(char *buf, size_t len, int codec, int fmt_is_wav_like, int sample_rate, int channels, int sample_fmt, int bits_per_raw_sample, int64_t bit_rate)
{
    char lay[64], tagbuf[64] = "";
    if (fmt_is_wav_like) {
        int tag = codec_wav_tag(codec);
        snprintf(tagbuf, sizeof tagbuf, " ([%d][%d][%d][%d] / 0x%04X)", tag & 0xff, (tag >> 8) & 0xff, (tag >> 16) & 0xff, (tag >> 24) & 0xff, tag);
    }
    char fmtbuf[64];
    const char *fname = sample_fmt_name(sample_fmt);
    if (bits_per_raw_sample > 0 && bits_per_raw_sample < sample_fmt_bytes(sample_fmt) * 8 && sample_fmt != FMT_FLT && sample_fmt != FMT_DBL)
        snprintf(fmtbuf, sizeof fmtbuf, "%s (%d bit)", fname, bits_per_raw_sample);
    else snprintf(fmtbuf, sizeof fmtbuf, "%s", fname);
    int n = snprintf(buf, len, "%s%s, %d Hz, %s, %s", codec_name(codec), tagbuf, sample_rate, channel_layout_name(channels, lay, sizeof lay), fmtbuf);
    if (bit_rate > 0) snprintf(buf + n, len - n, ", %" PRId64 " kb/s", bit_rate / 1000);
}

static void dump_input(Input *in)
{
    log_msg(LOG_INFO, "Input #%d, %s, from '%s':\n", in->index, in->fmt_name, in->url);
    dump_metadata(&in->metadata, "  ");
    char dur[64], br[64];
    if (in->duration_us >= 0) fmt_duration_hms(in->duration_us + 5000, dur, sizeof dur);
    else snprintf(dur, sizeof dur, "N/A");
    char line[256];
    int n = snprintf(line, sizeof line, "  Duration: %s", dur);
    if (in->start_time_us >= 0) {
        n += snprintf(line + n, sizeof line - n, ", start: %d.%06d", (int)(in->start_time_us / 1000000), (int)(in->start_time_us % 1000000));
    }
    if (in->is_lavfi) {
        fmt_bitrate_kb(in->bit_rate, br, sizeof br);
    } else if (in->fmt_bit_rate > 0) fmt_bitrate_kb(in->fmt_bit_rate, br, sizeof br);
    else snprintf(br, sizeof br, "N/A");
    snprintf(line + n, sizeof line - n, ", bitrate: %s\n", br);
    log_msg(LOG_INFO, "%s", line);
    char desc[256];
    int wavlike = !strcmp(in->fmt_name, "wav");
    stream_desc(desc, sizeof desc, in->codec, wavlike, in->sample_rate, in->channels, in->sample_fmt, in->bits_per_raw_sample, in->codec == CODEC_FLAC ? 0 : in->bit_rate);
    log_msg(LOG_INFO, "  Stream #%d:0: Audio: %s\n", in->index, desc);
}

static void dump_output(Output *o)
{
    log_msg(LOG_INFO, "Output #%d, %s, to '%s':\n", o->index, o->fmt_name, o->url);
    dump_metadata(&o->metadata, "  ");
    OutStream *st = &o->st;
    char desc[256];
    int wavlike = !strcmp(o->fmt_name, "wav");
    int64_t br;
    if (st->copy) br = st->in->codec == CODEC_FLAC ? 0 : st->in->bit_rate;
    else if (st->codec == CODEC_FLAC) br = 128000;
    else br = (int64_t)st->sample_rate * st->channels * codec_bits(st->codec);
    int bprs = st->copy ? st->in->bits_per_raw_sample : st->bits_per_raw_sample;
    int sfmt = st->copy ? st->in->sample_fmt : st->sample_fmt;
    if (!st->copy && st->codec != CODEC_FLAC) bprs = 0;
    stream_desc(desc, sizeof desc, st->copy ? st->in->codec : st->codec, wavlike, st->sample_rate, st->channels, sfmt, bprs, br);
    log_msg(LOG_INFO, "  Stream #%d:0: Audio: %s\n", o->index, desc);
    dump_metadata(&st->metadata, "    ");
}

/* ---------------- sample conversion ---------------- */
static void convert_samples(const uint8_t *src, int sfmt, uint8_t *dst, int dfmt, int64_t count)
{
    for (int64_t i = 0; i < count; i++) {
        int32_t v32 = 0; double vd = 0; int is_float = 0;
        switch (sfmt) {
        case FMT_U8: v32 = ((int)src[i] - 128) << 24; break;
        case FMT_S16: v32 = (int32_t)((uint32_t)(int16_t)rl16(src + 2 * i) << 16); break;
        case FMT_S32: v32 = (int32_t)rl32(src + 4 * i); break;
        case FMT_FLT: { uint32_t u = rl32(src + 4 * i); float f; memcpy(&f, &u, 4); vd = f; is_float = 1; break; }
        case FMT_DBL: { uint64_t u = rl64(src + 8 * i); memcpy(&vd, &u, 8); is_float = 1; break; }
        }
        if (is_float) {
            switch (dfmt) {
            case FMT_U8: { long v = lrint(vd * 128.0); dst[i] = (uint8_t)(clip_int((int)v, -128, 127) + 128); break; }
            case FMT_S16: { long v = lrint(vd * 32768.0); wl16(dst + 2 * i, (uint16_t)clip_int((int)v, -32768, 32767)); break; }
            case FMT_S32: { double x = vd * 2147483648.0; int64_t v = x >= 2147483647.0 ? INT32_MAX : x <= -2147483648.0 ? INT32_MIN : llrint(x); wl32(dst + 4 * i, (uint32_t)v); break; }
            case FMT_FLT: { float f = (float)vd; uint32_t u; memcpy(&u, &f, 4); wl32(dst + 4 * i, u); break; }
            case FMT_DBL: { uint64_t u; memcpy(&u, &vd, 8); wl64(dst + 8 * i, u); break; }
            }
        } else {
            switch (dfmt) {
            case FMT_U8: dst[i] = (uint8_t)((v32 >> 24) + 128); break;
            case FMT_S16: wl16(dst + 2 * i, (uint16_t)(v32 >> 16)); break;
            case FMT_S32: wl32(dst + 4 * i, (uint32_t)v32); break;
            case FMT_FLT: { float f = (float)(v32 * (1.0 / 2147483648.0)); uint32_t u; memcpy(&u, &f, 4); wl32(dst + 4 * i, u); break; }
            case FMT_DBL: { double d = v32 * (1.0 / 2147483648.0); uint64_t u; memcpy(&u, &d, 8); wl64(dst + 8 * i, u); break; }
            }
        }
    }
}

/* channel remix for s16/s32 integer data (mono<->stereo) */
static uint8_t *remix_channels(const uint8_t *src, int fmt, int in_ch, int out_ch, int64_t nb)
{
    int bytes = sample_fmt_bytes(fmt);
    uint8_t *dst = malloc((size_t)nb * out_ch * bytes + 16);
    for (int64_t i = 0; i < nb; i++) {
        if (in_ch == 1 && out_ch == 2) {
            if (fmt == FMT_S16) {
                int32_t m = (int16_t)rl16(src + 2 * i);
                int32_t v = (m * 23170 + 16384) >> 15;
                wl16(dst + 4 * i, (uint16_t)v); wl16(dst + 4 * i + 2, (uint16_t)v);
            } else if (fmt == FMT_S32) {
                int64_t m = (int32_t)rl32(src + 4 * i);
                int32_t v = (int32_t)((m * 23170 + 16384) >> 15);
                wl32(dst + 8 * i, (uint32_t)v); wl32(dst + 8 * i + 4, (uint32_t)v);
            } else {
                memcpy(dst + (size_t)i * 2 * bytes, src + (size_t)i * bytes, bytes);
                memcpy(dst + (size_t)i * 2 * bytes + bytes, src + (size_t)i * bytes, bytes);
            }
        } else if (in_ch == 2 && out_ch == 1) {
            if (fmt == FMT_S16) {
                int32_t l = (int16_t)rl16(src + 4 * i), r = (int16_t)rl16(src + 4 * i + 2);
                int32_t v = (l * 16384 + r * 16384 + 16384) >> 15;
                wl16(dst + 2 * i, (uint16_t)clip_int(v, -32768, 32767));
            } else if (fmt == FMT_S32) {
                int64_t l = (int32_t)rl32(src + 8 * i), r = (int32_t)rl32(src + 8 * i + 4);
                int64_t v = (l * 16384 + r * 16384 + 16384) >> 15;
                if (v > INT32_MAX) v = INT32_MAX; if (v < INT32_MIN) v = INT32_MIN;
                wl32(dst + 4 * i, (uint32_t)v);
            } else {
                memcpy(dst + (size_t)i * bytes, src + (size_t)i * 2 * bytes, bytes);
            }
        } else {
            /* generic: copy min channels, zero rest */
            for (int c = 0; c < out_ch; c++) {
                if (c < in_ch) memcpy(dst + ((size_t)i * out_ch + c) * bytes, src + ((size_t)i * in_ch + c) * bytes, bytes);
                else memset(dst + ((size_t)i * out_ch + c) * bytes, fmt == FMT_U8 ? 128 : 0, bytes);
            }
        }
    }
    return dst;
}

/* encode pcm from interleaved samples in fmt to codec bytes */
static void pcm_encode(int codec, const uint8_t *src, int fmt, int64_t count, ByteBuf *out)
{
    int bytes = sample_fmt_bytes(fmt);
    for (int64_t i = 0; i < count; i++) {
        const uint8_t *p = src + i * bytes;
        uint8_t t[8];
        switch (codec) {
        case CODEC_PCM_U8: bb_putc(out, p[0]); break;
        case CODEC_PCM_S8: bb_putc(out, (uint8_t)(p[0] - 128)); break;
        case CODEC_PCM_S16LE: bb_put(out, p, 2); break;
        case CODEC_PCM_S16BE: t[0] = p[1]; t[1] = p[0]; bb_put(out, t, 2); break;
        case CODEC_PCM_S24LE: bb_put(out, p + 1, 3); break;
        case CODEC_PCM_S24BE: t[0] = p[3]; t[1] = p[2]; t[2] = p[1]; bb_put(out, t, 3); break;
        case CODEC_PCM_S32LE: bb_put(out, p, 4); break;
        case CODEC_PCM_S32BE: t[0] = p[3]; t[1] = p[2]; t[2] = p[1]; t[3] = p[0]; bb_put(out, t, 4); break;
        case CODEC_PCM_F32LE: bb_put(out, p, 4); break;
        case CODEC_PCM_F64LE: bb_put(out, p, 8); break;
        case CODEC_PCM_ALAW: case CODEC_PCM_MULAW: {
            int16_t s = (int16_t)rl16(p);
            uint8_t o;
            if (codec == CODEC_PCM_ALAW) {
                int sign = s >= 0 ? 0x80 : 0; int mag = s >= 0 ? s : -s - 1; mag >>= 3;
                int exp = 0; if (mag > 15) { exp = 1; while (mag > 31) { mag >>= 1; exp++; } }
                o = (uint8_t)((sign | (exp << 4) | (mag & 0x0f)) ^ 0x55);
            } else {
                int sign = s < 0 ? 0x80 : 0; int mag = (s < 0 ? -s - 1 : s) >> 2; mag += 33;
                int exp = 0; while (mag > 0x3f) { mag >>= 1; exp++; }
                o = (uint8_t)~(sign | (exp << 4) | ((mag >> 1) & 0x0f));
            }
            bb_putc(out, o);
            break;
        }
        }
    }
}

/* ---------------- stats ---------------- */
static double elapsed_seconds(void)
{
    struct timeval now; gettimeofday(&now, NULL);
    return (now.tv_sec - t_start.tv_sec) + (now.tv_usec - t_start.tv_usec) / 1e6;
}

static void print_report(Output *o, int64_t pts_us, int final)
{
    if (opt_stats == 0) return;
    if (log_level < LOG_INFO) return;
    char buf[512]; int n = 0;
    int size_known = strcmp(o->fmt_name, "null") != 0;
    int64_t total = o->total_size;
    if (size_known) n += snprintf(buf + n, sizeof buf - n, "size=%8.0fKiB", total / 1024.0);
    else n += snprintf(buf + n, sizeof buf - n, "size=N/A");
    if (pts_us >= 0) {
        char t[64]; fmt_duration_hms(pts_us, t, sizeof t);
        n += snprintf(buf + n, sizeof buf - n, " time=%s", t);
    } else n += snprintf(buf + n, sizeof buf - n, " time=N/A");
    if (pts_us > 0 && size_known) n += snprintf(buf + n, sizeof buf - n, " bitrate=%6.1fkbits/s", total * 8 / (pts_us / 1000.0));
    else n += snprintf(buf + n, sizeof buf - n, " bitrate=N/A");
    double el = elapsed_seconds();
    if (pts_us >= 0 && el > 0) n += snprintf(buf + n, sizeof buf - n, " speed=%4.3gx", (pts_us / 1e6) / el);
    else n += snprintf(buf + n, sizeof buf - n, " speed=N/A");
    int h = (int)(el / 3600), m = (int)(el / 60) % 60; double s = fmod(el, 60.0);
    n += snprintf(buf + n, sizeof buf - n, " elapsed=%d:%02d:%05.2f", h, m, s);
    fprintf(stderr, "%s    %c", buf, final ? '\n' : '\r');
    fflush(stderr);
}

/* ---------------- main processing ---------------- */
static int output_format_from_name(const char *url, const char **fmt)
{
    const char *dot = strrchr(url, '.');
    const char *slash = strrchr(url, '/');
    if (!dot || (slash && dot < slash)) return -1;
    const char *ext = dot + 1;
    static const struct { const char *ext; const char *fmt; } tab[] = {
        { "wav", "wav" }, { "flac", "flac" }, { "md5", "md5" }, { "sw", "s16le" }, { "pcm", "s16le" }, { "raw", "s16le" }, { "sb", "s8" }, { "ub", "u8" },
        { "al", "alaw" }, { "ul", "mulaw" },
    };
    for (size_t i = 0; i < ARRAY_ELEMS(tab); i++) if (!strcasecmp(tab[i].ext, ext)) { *fmt = tab[i].fmt; return 0; }
    return -1;
}

static int known_output_format(const char *f)
{
    static const char *known[] = { "wav", "flac", "s16le", "s24le", "s32le", "u8", "s8", "f32le", "f64le", "s16be", "s24be", "s32be", "alaw", "mulaw",
                                   "md5", "hash", "framecrc", "framemd5", "crc", "null", NULL };
    for (int i = 0; known[i]; i++) if (!strcmp(known[i], f)) return 1;
    return 0;
}

static int default_codec_for_format(const char *f)
{
    if (!strcmp(f, "flac")) return CODEC_FLAC;
    if (!strcmp(f, "s24le")) return CODEC_PCM_S24LE;
    if (!strcmp(f, "s32le")) return CODEC_PCM_S32LE;
    if (!strcmp(f, "u8")) return CODEC_PCM_U8;
    if (!strcmp(f, "s8")) return CODEC_PCM_S8;
    if (!strcmp(f, "f32le")) return CODEC_PCM_F32LE;
    if (!strcmp(f, "f64le")) return CODEC_PCM_F64LE;
    if (!strcmp(f, "s16be")) return CODEC_PCM_S16BE;
    if (!strcmp(f, "s24be")) return CODEC_PCM_S24BE;
    if (!strcmp(f, "s32be")) return CODEC_PCM_S32BE;
    if (!strcmp(f, "alaw")) return CODEC_PCM_ALAW;
    if (!strcmp(f, "mulaw")) return CODEC_PCM_MULAW;
    return CODEC_PCM_S16LE;
}

static int codec_supported_by_format(const char *f, int codec)
{
    if (!strcmp(f, "flac")) return codec == CODEC_FLAC;
    if (!strcmp(f, "wav")) return codec != CODEC_PCM_S16BE && codec != CODEC_PCM_S24BE && codec != CODEC_PCM_S32BE && codec != CODEC_PCM_S8;
    if (!strcmp(f, "md5") || !strcmp(f, "hash") || !strcmp(f, "framecrc") || !strcmp(f, "framemd5") || !strcmp(f, "crc") || !strcmp(f, "null")) return 1;
    return codec == default_codec_for_format(f);
}

static int parse_flac_opt_enum(const char *name, const char *val, int *out)
{
    if (!strcmp(name, "lpc_type")) {
        static const char *n[] = { "none", "fixed", "levinson", "cholesky" };
        for (int i = 0; i < 4; i++) if (!strcmp(val, n[i])) { *out = i; return 0; }
    } else if (!strcmp(name, "prediction_order_method")) {
        static const char *n[] = { "estimation", "2level", "4level", "8level", "search", "log" };
        for (int i = 0; i < 6; i++) if (!strcmp(val, n[i])) { *out = i; return 0; }
    } else if (!strcmp(name, "ch_mode")) {
        static const char *n[] = { "auto", "indep", "left_side", "right_side", "mid_side" };
        for (int i = 0; i < 5; i++) if (!strcmp(val, n[i])) { *out = i - 1; return 0; }
    }
    return parse_int_opt(name, val, out);
}

static int parse_bool_opt(const char *val)
{
    if (!strcmp(val, "true") || !strcmp(val, "1") || !strcmp(val, "yes") || !strcmp(val, "on")) return 1;
    if (!strcmp(val, "false") || !strcmp(val, "0") || !strcmp(val, "no") || !strcmp(val, "off")) return 0;
    return atoi(val) != 0;
}

static int parse_strict(const char *val)
{
    if (!strcmp(val, "very")) return 2;
    if (!strcmp(val, "strict")) return 1;
    if (!strcmp(val, "normal")) return 0;
    if (!strcmp(val, "unofficial")) return -1;
    if (!strcmp(val, "experimental")) return -2;
    return atoi(val);
}

static int has_flag(const char *val, const char *flag)
{
    /* "+bitexact", "bitexact", "+flag1+flag2" */
    const char *p = val;
    while (*p) {
        int neg = 0;
        if (*p == '+') p++; else if (*p == '-') { neg = 1; p++; }
        const char *e = p; while (*e && *e != '+' && *e != '-') e++;
        if ((size_t)(e - p) == strlen(flag) && !strncmp(p, flag, e - p) && !neg) return 1;
        p = e;
    }
    return 0;
}

static int64_t round_samples(int64_t us, int sample_rate)
{
    long double v = (long double)us * sample_rate / 1000000.0L;
    return (int64_t)(v + 0.5L);
}

static int do_overwrite_check(Output *o)
{
    if (o->is_pipe) return 0;
    struct stat stbuf;
    if (stat(o->url, &stbuf) != 0) return 0;
    if (S_ISDIR(stbuf.st_mode)) return 0;
    if (opt_overwrite == 1) return 0;
    if (opt_overwrite == 0) {
        log_msg(LOG_FATAL, "File '%s' already exists. Exiting.\n", o->url);
        return ERR_EXIT;
    }
    if (opt_stdin && isatty(0) == 0) {
        /* non-interactive stdin: ffmpeg still reads a line */
    }
    if (!opt_stdin) {
        log_msg(LOG_FATAL, "File '%s' already exists. Exiting.\n", o->url);
        return ERR_EXIT;
    }
    log_flush();
    fprintf(stderr, "File '%s' already exists. Overwrite? [y/N] ", o->url);
    fflush(stderr);
    int c = getchar();
    int first = c;
    while (c != '\n' && c != EOF) c = getchar();
    if (first != 'y' && first != 'Y') {
        log_msg(LOG_FATAL, "Not overwriting - exiting\n");
        return ERR_EXIT;
    }
    return 0;
}

static int write_output_file(Output *o)
{
    if (!strcmp(o->fmt_name, "null")) return 0;
    if (o->is_pipe) {
        size_t w = fwrite(o->buf.data, 1, o->buf.len, stdout);
        fflush(stdout);
        if (w != o->buf.len) return ERR_EPIPE;
        return 0;
    }
    size_t w = fwrite(o->buf.data, 1, o->buf.len, o->fp);
    if (w != o->buf.len) return -errno;
    return 0;
}

static int run(void)
{
    int ret;
    /* open inputs */
    for (int i = 0; i < ninputs; i++) {
        Input *in = inputs[i];
        ret = input_open(in);
        if (ret < 0) {
            log_msg(LOG_ERROR, "Error opening input file %s.\n", in->url);
            log_msg(LOG_ERROR, "Error opening input files: %s\n", err_text(ret));
            return ret;
        }
        if (in->is_lavfi) {
            int64_t max = -1;
            if (in->opt_t_us > 0) max = round_samples(in->opt_t_us, in->sample_rate);
            if (in->sine.nb_samples_total == 0 && max < 0) {
                /* unlimited: generate up to the smallest output -t, else a bounded fallback */
                int64_t best = -1;
                for (int k = 0; k < noutputs; k++) {
                    if (outputs[k]->opt_t_us > 0) { int64_t s = round_samples(outputs[k]->opt_t_us, in->sample_rate); if (best < 0 || s < best) best = s; }
                    if (outputs[k]->opt_to_us > 0) { int64_t s = round_samples(outputs[k]->opt_to_us, in->sample_rate); if (best < 0 || s < best) best = s; }
                }
                max = best;
                if (max < 0) max = (int64_t)in->sample_rate * 3600; /* safety: one hour */
            }
            lavfi_generate(in, max);
        }
        if (in->layout_guessed && !in->is_lavfi) {
            char ctx[64]; snprintf(ctx, sizeof ctx, "aist#%d:0/%s", in->index, codec_name(in->codec));
            char lay[64];
            log_ctx(LOG_WARNING, ctx, "Guessed Channel Layout: %s\n", channel_layout_name(in->channels, lay, sizeof lay));
        }
        dump_input(in);
    }
    if (noutputs == 0) {
        log_msg(LOG_FATAL, "At least one output file must be specified\n");
        return 1;
    }
    /* set up outputs */
    for (int i = 0; i < noutputs; i++) {
        Output *o = outputs[i];
        OutStream *st = &o->st;
        char octx[64]; snprintf(octx, sizeof octx, "out#%d", o->index);
        /* format */
        if (o->opt_format) {
            if (!known_output_format(o->opt_format)) {
                log_ctx(LOG_ERROR, "AVFormatContext", "Requested output format '%s' is not known.\n", o->opt_format);
                log_ctx(LOG_ERROR, octx, "Error initializing the muxer for %s: %s\n", o->url, err_text(ERR_EINVAL));
                log_msg(LOG_ERROR, "Error opening output file %s.\n", o->url);
                log_msg(LOG_ERROR, "Error opening output files: %s\n", err_text(ERR_EINVAL));
                return ERR_EINVAL;
            }
            o->fmt_name = o->opt_format;
        } else {
            if (!strcmp(o->url, "-") || !strncmp(o->url, "pipe:", 5) || output_format_from_name(o->url, &o->fmt_name) < 0) {
                log_ctx(LOG_ERROR, "AVFormatContext", "Unable to choose an output format for '%s'; use a standard extension for the filename or specify the format manually.\n", o->url);
                log_ctx(LOG_ERROR, octx, "Error initializing the muxer for %s: %s\n", o->url, err_text(ERR_EINVAL));
                log_msg(LOG_ERROR, "Error opening output file %s.\n", o->url);
                log_msg(LOG_ERROR, "Error opening output files: %s\n", err_text(ERR_EINVAL));
                return ERR_EINVAL;
            }
        }
        snprintf(octx, sizeof octx, "out#%d/%s", o->index, o->fmt_name);
        o->is_pipe = !strcmp(o->url, "-") || !strncmp(o->url, "pipe:", 5);
        /* select input stream */
        Input *in = NULL;
        if (o->has_map) {
            if (o->map_file < 0 || o->map_file >= ninputs) {
                log_msg(LOG_FATAL, "Invalid input file index: %d.\n", o->map_file);
                return ERR_EINVAL;
            }
            in = inputs[o->map_file];
            if (o->map_stream > 0) {
                log_msg(LOG_ERROR, "Stream map '%d:%d' matches no streams.\n", o->map_file, o->map_stream);
                log_msg(LOG_ERROR, "To ignore this, add a trailing '?' to the map.\n");
                return ERR_EINVAL;
            }
        } else if (ninputs > 0 && !o->no_audio) {
            in = inputs[0];
        }
        if (!in || o->no_audio) {
            log_msg(LOG_INFO, "Output #%d, %s, to '%s':\n", o->index, o->fmt_name, o->url);
            log_ctx(LOG_ERROR, octx, "Output file does not contain any stream\n");
            log_msg(LOG_ERROR, "Error opening output file %s.\n", o->url);
            log_msg(LOG_ERROR, "Error opening output files: %s\n", err_text(ERR_EINVAL));
            return ERR_EINVAL;
        }
        st->in = in;
        o->nstreams = 1;
        /* codec selection */
        const char *cname = NULL;
        for (int k = 0; k < o->opts.n; k++) {
            const char *n = o->opts.names[k];
            if ((!strcmp(n, "c") || !strcmp(n, "codec")) && spec_matches_audio(o->opts.specs[k])) cname = o->opts.vals[k];
            else if (!strcmp(n, "acodec")) cname = o->opts.vals[k];
        }
        if (cname) {
            if (!strcmp(cname, "copy")) { st->copy = 1; st->codec = in->codec; }
            else {
                st->codec = codec_by_name(cname);
                if (st->codec == CODEC_NONE) {
                    char sctx[64]; snprintf(sctx, sizeof sctx, "aost#%d:0", o->index);
                    log_ctx(LOG_ERROR, sctx, "Unknown encoder '%s'\n", cname);
                    log_ctx(LOG_ERROR, sctx, "Error selecting an encoder\n");
                    log_msg(LOG_ERROR, "Error opening output file %s.\n", o->url);
                    log_msg(LOG_ERROR, "Error opening output files: %s\n", err_text(ERR_ENCODER_NOT_FOUND));
                    return ERR_ENCODER_NOT_FOUND;
                }
            }
        } else {
            st->codec = default_codec_for_format(o->fmt_name);
        }
        if (!codec_supported_by_format(o->fmt_name, st->copy ? in->codec : st->codec)) {
            char sctx[64]; snprintf(sctx, sizeof sctx, "aost#%d:0", o->index);
            if (st->copy) {
                log_ctx(LOG_ERROR, octx, "Could not write header (incorrect codec parameters ?): %s\n", err_text(ERR_EINVAL));
            } else {
                log_ctx(LOG_ERROR, octx, "Could not write header (incorrect codec parameters ?): %s\n", err_text(ERR_EINVAL));
            }
            log_msg(LOG_ERROR, "Error opening output file %s.\n", o->url);
            log_msg(LOG_ERROR, "Error opening output files: %s\n", err_text(ERR_EINVAL));
            (void)sctx;
            return ERR_EINVAL;
        }
        /* stream parameters */
        st->sample_rate = in->sample_rate;
        st->channels = in->channels;
        const char *ar = NULL, *ac = NULL, *sfmt = NULL;
        for (int k = 0; k < o->opts.n; k++) {
            const char *n = o->opts.names[k];
            if (!strcmp(n, "ar") && spec_matches_audio(o->opts.specs[k])) ar = o->opts.vals[k];
            if (!strcmp(n, "ac") && spec_matches_audio(o->opts.specs[k])) ac = o->opts.vals[k];
            if (!strcmp(n, "sample_fmt") && spec_matches_audio(o->opts.specs[k])) sfmt = o->opts.vals[k];
        }
        if (ar && !st->copy) st->sample_rate = atoi(ar);
        if (ac && !st->copy) st->channels = atoi(ac);
        if (st->copy) {
            st->sample_fmt = in->sample_fmt;
            st->bits_per_raw_sample = in->bits_per_raw_sample;
        } else {
            if (st->codec == CODEC_FLAC) {
                int want = in->sample_fmt == FMT_S32 ? FMT_S32 : FMT_S16;
                if (in->sample_fmt == FMT_FLT || in->sample_fmt == FMT_DBL) want = FMT_S32;
                if (in->sample_fmt == FMT_U8) want = FMT_S16;
                if (sfmt) {
                    int f = sample_fmt_by_name(sfmt);
                    if (f != FMT_S16 && f != FMT_S32) {
                        log_msg(LOG_ERROR, "Unsupported sample format '%s' for encoder flac\n", sfmt);
                        return ERR_EINVAL;
                    }
                    want = f;
                }
                st->sample_fmt = want;
                int bprs = in->bits_per_raw_sample;
                if (bprs > sample_fmt_bytes(want) * 8 || bprs == 0) bprs = sample_fmt_bytes(want) * 8;
                st->bits_per_raw_sample = bprs;
            } else {
                st->sample_fmt = codec_sample_fmt(st->codec);
                st->bits_per_raw_sample = 0;
            }
        }
        /* metadata */
        dict_copy(&o->metadata, &in->metadata);
        for (int k = 0; k < o->opts.n; k++) {
            if (!strcmp(o->opts.names[k], "metadata")) {
                const char *spec = o->opts.specs[k];
                char *kv = strdup(o->opts.vals[k]);
                char *eq = strchr(kv, '=');
                if (!eq) {
                    log_msg(LOG_FATAL, "No '=' character in metadata string %s.\n", kv);
                    free(kv);
                    return ERR_EINVAL;
                }
                *eq = 0;
                if (!*spec || !strcmp(spec, "g")) dict_set(&o->metadata, kv, *(eq + 1) ? eq + 1 : NULL);
                else if (spec[0] == 's') dict_set(&st->metadata, kv, *(eq + 1) ? eq + 1 : NULL);
                free(kv);
            }
        }
        /* bitexact flags */
        int fmt_bitexact = 0, codec_bitexact = 0;
        for (int k = 0; k < o->opts.n; k++) {
            const char *n = o->opts.names[k];
            if (!strcmp(n, "fflags") && has_flag(o->opts.vals[k], "bitexact")) fmt_bitexact = 1;
            if (!strcmp(n, "flags") && has_flag(o->opts.vals[k], "bitexact")) codec_bitexact = 1;
            if (!strcmp(n, "bitexact")) fmt_bitexact = codec_bitexact = 1;
        }
        if (opt_bitexact_global) fmt_bitexact = codec_bitexact = 1;
        if (fmt_bitexact) codec_bitexact = 1;
        o->bitexact = fmt_bitexact;
        if (!st->copy) {
            char enc[128];
            if (codec_bitexact) snprintf(enc, sizeof enc, "Lavc %s", codec_name(st->codec));
            else snprintf(enc, sizeof enc, "%s %s", LAVC_IDENT, codec_name(st->codec));
            dict_set(&st->metadata, "encoder", enc);
        }
        if (!fmt_bitexact) dict_set(&o->metadata, "encoder", LAVF_IDENT);
        else dict_del(&o->metadata, "encoder");
        if (!strcmp(o->fmt_name, "wav")) {
            /* convert generic keys to RIFF tags */
            Dict conv = {0};
            for (int k = 0; k < o->metadata.n; k++) {
                const char *tag = riff_tag_for_key(o->metadata.keys[k]);
                dict_set(&conv, tag ? tag : o->metadata.keys[k], o->metadata.vals[k]);
            }
            dict_free(&o->metadata);
            o->metadata = conv;
        }
        /* flac encoder options */
        flacenc_default_options(&st->flacopts);
        o->write_header = 1;
        for (int k = 0; k < o->opts.n; k++) {
            const char *n = o->opts.names[k], *v = o->opts.vals[k];
            int iv;
            if (!strcmp(n, "compression_level")) parse_int_opt(n, v, &st->flacopts.compression_level);
            else if (!strcmp(n, "frame_size")) parse_int_opt(n, v, &st->flacopts.frame_size);
            else if (!strcmp(n, "lpc_coeff_precision")) parse_int_opt(n, v, &st->flacopts.lpc_coeff_precision);
            else if (!strcmp(n, "lpc_type")) { if (!parse_flac_opt_enum(n, v, &iv)) st->flacopts.lpc_type = iv; }
            else if (!strcmp(n, "lpc_passes")) parse_int_opt(n, v, &st->flacopts.lpc_passes);
            else if (!strcmp(n, "min_partition_order")) parse_int_opt(n, v, &st->flacopts.min_partition_order);
            else if (!strcmp(n, "max_partition_order")) parse_int_opt(n, v, &st->flacopts.max_partition_order);
            else if (!strcmp(n, "prediction_order_method")) { if (!parse_flac_opt_enum(n, v, &iv)) st->flacopts.prediction_order_method = iv; }
            else if (!strcmp(n, "ch_mode")) { if (!parse_flac_opt_enum(n, v, &iv)) st->flacopts.ch_mode = iv; }
            else if (!strcmp(n, "exact_rice_parameters")) st->flacopts.exact_rice_parameters = parse_bool_opt(v);
            else if (!strcmp(n, "multi_dim_quant")) st->flacopts.multi_dim_quant = parse_bool_opt(v);
            else if (!strcmp(n, "min_prediction_order")) parse_int_opt(n, v, &st->flacopts.min_prediction_order);
            else if (!strcmp(n, "max_prediction_order")) parse_int_opt(n, v, &st->flacopts.max_prediction_order);
            else if (!strcmp(n, "strict")) st->flacopts.strict = parse_strict(v);
            else if (!strcmp(n, "write_header")) o->write_header = parse_bool_opt(v);
            else if (!strcmp(n, "hash")) { free(o->hash_algo); o->hash_algo = strdup(v); }
            else if (!strcmp(n, "rf64")) { if (!strcmp(v, "always")) o->wav_rf64 = 1; else if (!strcmp(v, "auto")) o->wav_rf64 = -1; else o->wav_rf64 = atoi(v); }
        }
        /* create output file now (ffmpeg opens the file at this stage) */
        ret = do_overwrite_check(o);
        if (ret < 0) {
            log_msg(LOG_ERROR, "Error opening output file %s.\n", o->url);
            return ret;
        }
        if (!o->is_pipe && strcmp(o->fmt_name, "null") != 0) {
            const char *path = o->url;
            if (!strncmp(path, "file:", 5)) path += 5;
            o->fp = fopen(path, "wb");
            if (!o->fp) {
                int e = -errno;
                log_ctx(LOG_ERROR, octx, "Error opening output %s: %s\n", o->url, err_text(e));
                log_msg(LOG_ERROR, "Error opening output file %s.\n", o->url);
                log_msg(LOG_ERROR, "Error opening output files: %s\n", err_text(e));
                return e;
            }
        }
    }
    /* stream mapping */
    log_msg(LOG_INFO, "Stream mapping:\n");
    for (int i = 0; i < noutputs; i++) {
        Output *o = outputs[i];
        OutStream *st = &o->st;
        if (st->copy)
            log_msg(LOG_INFO, "  Stream #%d:0 -> #%d:0 (copy)\n", st->in->index, o->index);
        else
            log_msg(LOG_INFO, "  Stream #%d:0 -> #%d:0 (%s (native) -> %s (native))\n", st->in->index, o->index, codec_name(st->in->codec), codec_name(st->codec));
    }
    /* copy-mode outputs print their header dump before "Press [q]" */
    int all_copy = 1;
    for (int i = 0; i < noutputs; i++) if (!outputs[i]->st.copy) all_copy = 0;
    if (all_copy) {
        for (int i = 0; i < noutputs; i++) {
            Output *o = outputs[i];
            dump_output(o);
        }
    }
    if (opt_stdin) log_msg(LOG_INFO, "Press [q] to stop, [?] for help\n");

    /* encode */
    int final_ret = 0;
    for (int i = 0; i < noutputs; i++) {
        Output *o = outputs[i];
        OutStream *st = &o->st;
        Input *in = st->in;
        char octx[64]; snprintf(octx, sizeof octx, "out#%d/%s", o->index, o->fmt_name);
        int64_t pts_us = -1;
        /* apply trimming */
        int64_t start_sample = 0, end_sample = in->nb_samples;
        if (in->opt_ss_us > 0) start_sample = MIN(round_samples(in->opt_ss_us, in->sample_rate), in->nb_samples);
        if (in->opt_t_us > 0) end_sample = MIN(end_sample, start_sample + round_samples(in->opt_t_us, in->sample_rate));
        if (o->opt_t_us > 0) end_sample = MIN(end_sample, start_sample + round_samples(o->opt_t_us, in->sample_rate));
        if (o->opt_to_us > 0) end_sample = MIN(end_sample, round_samples(o->opt_to_us, in->sample_rate));
        if (o->opt_ss_us > 0) start_sample = MIN(start_sample + round_samples(o->opt_ss_us, in->sample_rate), end_sample);
        int64_t nb = end_sample - start_sample;
        if (nb < 0) nb = 0;

        if (st->copy) {
            uint8_t si[34];
            if (in->codec == CODEC_FLAC) memcpy(si, in->flac_streaminfo, 34);
            ret = mux_write_header(o, si);
            if (ret < 0) {
                log_ctx(LOG_ERROR, octx, "Could not write header (incorrect codec parameters ?): %s\n", err_text(ret));
                return ret;
            }
            if (in->codec == CODEC_FLAC && (!strcmp(o->fmt_name, "framecrc") || !strcmp(o->fmt_name, "framemd5")))
                mux_write_extradata_line(o, si, 34);
            for (int k = 0; k < in->npkts; k++) {
                Packet *p = &in->pkts[k];
                if (p->pts + p->nb_samples <= start_sample) continue;
                if (p->pts >= end_sample) break;
                Packet q = *p;
                q.pts = p->pts - start_sample;
                mux_write_packet(o, &q, NULL, 0);
                st->packets_muxed++; st->bytes_muxed += q.size; o->data_size += q.size;
                pts_us = (int64_t)((long double)(q.pts + q.nb_samples) * 1000000.0L / in->sample_rate + 0.5L);
            }
            mux_write_trailer(o, si, 0);
        } else {
            /* decode -> convert -> remix -> encode */
            int in_fmt = in->sample_fmt;
            int in_bytes = sample_fmt_bytes(in_fmt);
            const uint8_t *src = in->pcm + (size_t)start_sample * in->channels * in_bytes;
            uint8_t *conv = NULL; const uint8_t *data = src; int cur_fmt = in_fmt;
            if (st->sample_fmt != in_fmt) {
                conv = malloc((size_t)nb * in->channels * sample_fmt_bytes(st->sample_fmt) + 16);
                convert_samples(src, in_fmt, conv, st->sample_fmt, nb * in->channels);
                data = conv; cur_fmt = st->sample_fmt;
            }
            uint8_t *mixed = NULL;
            if (st->channels != in->channels) {
                mixed = remix_channels(data, cur_fmt, in->channels, st->channels, nb);
                data = mixed;
            }
            if (st->sample_rate != in->sample_rate) {
                log_ctx(LOG_ERROR, octx, "Sample rate conversion is not supported by this build\n");
                free(conv); free(mixed);
                return ERR_PATCHWELCOME;
            }
            int out_bytes = sample_fmt_bytes(st->sample_fmt);
            int header_written = 0;
            uint8_t si[34] = {0};
            if (st->codec == CODEC_FLAC) {
                char err[256];
                int r = flacenc_init(&st->flacenc, st->channels, st->sample_rate, st->sample_fmt == FMT_S32 ? 32 : 16, st->bits_per_raw_sample, &st->flacopts, err, sizeof err);
                if (r < 0) {
                    char ectx[64]; snprintf(ectx, sizeof ectx, "aost#%d:0/flac", o->index);
                    log_ctx(LOG_ERROR, "flac", "%s\n", err);
                    log_msg(LOG_ERROR, "[aost#%d:0/flac @ %s] [enc:flac @ %s] Error while opening encoder - maybe incorrect parameters such as bit_rate, rate, width or height.\n", o->index, fake_addr(ectx), fake_addr("enc:flac"));
                    char afctx[64]; snprintf(afctx, sizeof afctx, "af#%d:0", o->index);
                    log_ctx(LOG_ERROR, afctx, "Error sending frames to consumers: %s\n", err_text(ERR_EINVAL));
                    log_ctx(LOG_ERROR, afctx, "Task finished with error code: -22 (%s)\n", err_text(ERR_EINVAL));
                    log_ctx(LOG_ERROR, afctx, "Terminating thread with return code -22 (%s)\n", err_text(ERR_EINVAL));
                    log_msg(LOG_ERROR, "[aost#%d:0/flac @ %s] [enc:flac @ %s] Could not open encoder before EOF\n", o->index, fake_addr(ectx), fake_addr("enc:flac"));
                    log_ctx(LOG_ERROR, ectx, "Task finished with error code: -22 (%s)\n", err_text(ERR_EINVAL));
                    log_ctx(LOG_ERROR, ectx, "Terminating thread with return code -22 (%s)\n", err_text(ERR_EINVAL));
                    log_ctx(LOG_ERROR, octx, "Nothing was written into output file, because at least one of its streams received no packets.\n");
                    print_report(o, -1, 1);
                    log_msg(LOG_ERROR, "Conversion failed!\n");
                    free(conv); free(mixed);
                    return ERR_EINVAL;
                }
                if (st->flacenc.warn_msg[0]) log_ctx(LOG_WARNING, "flac", "%s\n", st->flacenc.warn_msg);
                st->frame_size = st->flacenc.blocksize;
                st->bits_per_raw_sample = st->flacenc.bps;
                st->sample_fmt = st->flacenc.bps > 16 ? FMT_S32 : FMT_S16;
                flacenc_write_streaminfo(&st->flacenc, si, 0);
            }
            /* chunking */
            int64_t pos = 0;
            int pkt_index = 0;
            int64_t out_pts = 0;
            ByteBuf frame = {0};
            int wrote_any = 0;
            /* find the first input packet overlapping start_sample for pcm chunking */
            int64_t in_pkt_pos = 0;
            while (pkt_index < in->npkts && in->pkts[pkt_index].pts + in->pkts[pkt_index].nb_samples <= start_sample) pkt_index++;
            if (pkt_index < in->npkts) in_pkt_pos = in->pkts[pkt_index].pts;
            while (pos < nb || (!wrote_any && nb == 0 && 0)) {
                int n;
                if (st->codec == CODEC_FLAC) n = (int)MIN((int64_t)st->frame_size, nb - pos);
                else {
                    /* pcm: one packet per input frame */
                    if (pkt_index < in->npkts) {
                        int64_t pend = in->pkts[pkt_index].pts + in->pkts[pkt_index].nb_samples;
                        n = (int)MIN(pend - (start_sample + pos), nb - pos);
                        if (n <= 0) { pkt_index++; continue; }
                        pkt_index++;
                    } else n = (int)(nb - pos);
                    (void)in_pkt_pos;
                }
                if (n <= 0) break;
                frame.len = 0;
                if (st->codec == CODEC_FLAC) {
                    int32_t *smp = malloc(sizeof(int32_t) * n * st->channels);
                    for (int k = 0; k < n * st->channels; k++) {
                        const uint8_t *p = data + ((size_t)pos * st->channels + k) * out_bytes;
                        smp[k] = out_bytes == 2 ? (int16_t)rl16(p) : (int32_t)rl32(p);
                    }
                    flacenc_encode_frame(&st->flacenc, smp, n, &frame);
                    free(smp);
                } else {
                    pcm_encode(st->codec, data + (size_t)pos * st->channels * out_bytes, st->sample_fmt, (int64_t)n * st->channels, &frame);
                }
                if (!header_written) {
                    ret = mux_write_header(o, si);
                    if (ret < 0) {
                        log_ctx(LOG_ERROR, octx, "Could not write header (incorrect codec parameters ?): %s\n", err_text(ret));
                        char afctx[64]; snprintf(afctx, sizeof afctx, "af#%d:0", o->index);
                        log_ctx(LOG_ERROR, afctx, "Error sending frames to consumers: %s\n", err_text(ret));
                        log_ctx(LOG_ERROR, afctx, "Task finished with error code: %d (%s)\n", ret, err_text(ret));
                        log_ctx(LOG_ERROR, afctx, "Terminating thread with return code %d (%s)\n", ret, err_text(ret));
                        log_ctx(LOG_ERROR, octx, "Nothing was written into output file, because at least one of its streams received no packets.\n");
                        free(conv); free(mixed); bb_free(&frame);
                        return ret;
                    }
                    if (st->codec == CODEC_FLAC && (!strcmp(o->fmt_name, "framecrc") || !strcmp(o->fmt_name, "framemd5")))
                        mux_write_extradata_line(o, si, 34);
                    if (!all_copy) dump_output(o);
                    header_written = 1;
                }
                Packet p = { .pts = out_pts, .nb_samples = n, .data = frame.data, .size = frame.len, .flags = 1 };
                mux_write_packet(o, &p, NULL, 0);
                st->packets_muxed++; st->bytes_muxed += frame.len; o->data_size += frame.len;
                st->frames_encoded++; st->samples_encoded += n;
                out_pts += n; pos += n;
                wrote_any = 1;
                pts_us = (int64_t)((long double)out_pts * 1000000.0L / st->sample_rate + 0.5L);
            }
            bb_free(&frame);
            if (!header_written) {
                /* no data at all */
                ret = mux_write_header(o, si);
                if (ret < 0) {
                    log_ctx(LOG_ERROR, octx, "Could not write header (incorrect codec parameters ?): %s\n", err_text(ret));
                    free(conv); free(mixed);
                    return ret;
                }
                if (!all_copy) dump_output(o);
                header_written = 1;
            }
            if (st->codec == CODEC_FLAC) {
                uint8_t fsi[34];
                flacenc_write_streaminfo(&st->flacenc, fsi, 1);
                /* final packet with new extradata (framecrc shows it) */
                if (!strcmp(o->fmt_name, "framecrc") || !strcmp(o->fmt_name, "framemd5")) {
                    Packet p = { .pts = out_pts, .nb_samples = 0, .data = (uint8_t *)"", .size = 0, .flags = 1 };
                    mux_write_packet(o, &p, fsi, 34);
                    st->packets_muxed++;
                }
                mux_write_trailer(o, fsi, 1);
                flacenc_free(&st->flacenc);
            } else {
                mux_write_trailer(o, NULL, 0);
            }
            free(conv); free(mixed);
        }
        o->total_size = strcmp(o->fmt_name, "null") ? (int64_t)o->buf.len : 0;
        ret = write_output_file(o);
        if (o->fp) { fclose(o->fp); o->fp = NULL; }
        if (ret < 0) {
            log_ctx(LOG_ERROR, octx, "Error writing trailer: %s\n", err_text(ret));
            final_ret = ret;
        }
        /* final stats */
        double overhead = -1;
        if (o->data_size > 0 && o->total_size >= o->data_size) overhead = 100.0 * (o->total_size - o->data_size) / (double)o->data_size;
        char ovbuf[64];
        if (overhead >= 0) snprintf(ovbuf, sizeof ovbuf, "%f%%", overhead); else snprintf(ovbuf, sizeof ovbuf, "unknown");
        log_ctx(LOG_INFO, octx, "video:%" PRId64 "KiB audio:%" PRId64 "KiB subtitle:0KiB other streams:0KiB global headers:0KiB muxing overhead: %s\n",
                (int64_t)0, (int64_t)llrint(o->data_size / 1024.0), ovbuf);
        if (i == noutputs - 1) print_report(o, pts_us, 1);
    }
    return final_ret;
}

/* ---------------- argument parsing ---------------- */
static int handle_global_opt(const char *name, const char *val)
{
    if (!strcmp(name, "y")) opt_overwrite = 1;
    else if (!strcmp(name, "n")) opt_overwrite = 0;
    else if (!strcmp(name, "hide_banner")) opt_hide_banner = 1;
    else if (!strcmp(name, "nohide_banner")) opt_hide_banner = 0;
    else if (!strcmp(name, "stats")) opt_stats = 1;
    else if (!strcmp(name, "nostats")) opt_stats = 0;
    else if (!strcmp(name, "stdin")) opt_stdin = 1;
    else if (!strcmp(name, "nostdin")) opt_stdin = 0;
    else if (!strcmp(name, "loglevel") || !strcmp(name, "v")) {
        if (log_parse_level(val) < 0) {
            log_msg(LOG_FATAL, "Failed to set value '%s' for option '%s': %s\n", val, name, err_text(ERR_EINVAL));
            return ERR_EINVAL;
        }
    }
    return 0;
}

static int info_option(const char *name, const char *arg)
{
    /* returns 1 if handled (and program should exit 0), 0 if not an info option */
    static const char *simple[] = { "L", "license", "version", "formats", "muxers", "demuxers", "devices", "codecs", "decoders", "encoders", "filters",
                                    "pix_fmts", "layouts", "sample_fmts", "colors", "bsfs", "protocols", "hwaccels", "dispositions", "buildconf", "sources", "sinks", NULL };
    int is_info = 0;
    for (int i = 0; simple[i]; i++) if (!strcmp(name, simple[i])) is_info = 1;
    if (!strcmp(name, "h") || !strcmp(name, "?") || !strcmp(name, "help") || !strcmp(name, "-help")) is_info = 2;
    if (!is_info) return 0;
    const char *text = NULL;
    char key[128];
    if (is_info == 2) {
        if (!arg) text = helptext_get("h");
        else if (!strcmp(arg, "long")) text = helptext_get("h_long");
        else if (!strcmp(arg, "full")) text = helptext_get("h_full");
        else {
            snprintf(key, sizeof key, "help_%s", arg);
            for (char *p = key; *p; p++) if (*p == '=') *p = '_';
            text = helptext_get(key);
            if (!text) {
                const char *eq = strchr(arg, '=');
                if (eq) {
                    char type[64]; size_t tl = MIN((size_t)(eq - arg), sizeof type - 1); memcpy(type, arg, tl); type[tl] = 0;
                    const char *name2 = eq + 1;
                    if (!strcmp(type, "decoder") || !strcmp(type, "encoder")) {
                        printf("Codec '%s' is not recognized by FFmpeg.\n", name2);
                        printf("\nExiting with exit code 0\n");
                        return 1;
                    } else if (!strcmp(type, "muxer") || !strcmp(type, "demuxer")) {
                        printf("Unknown format '%s'.\n", name2);
                        printf("\nExiting with exit code 0\n");
                        return 1;
                    } else if (!strcmp(type, "filter")) {
                        printf("Unknown filter '%s'.\n", name2);
                        printf("\nExiting with exit code 0\n");
                        return 1;
                    } else if (!strcmp(type, "bsf")) {
                        printf("Unknown bit stream filter '%s'.\n", name2);
                        printf("\nExiting with exit code 0\n");
                        return 1;
                    } else if (!strcmp(type, "protocol")) {
                        printf("Unknown protocol '%s'.\n", name2);
                        printf("\nExiting with exit code 0\n");
                        return 1;
                    }
                    printf("Unknown help option '%s'.\n", type);
                } else {
                    printf("Unknown help option '%s'.\n", arg);
                }
                text = helptext_get("h");
            }
        }
    } else {
        if (!strcmp(name, "license")) text = helptext_get("L");
        else text = helptext_get(name);
    }
    if (text) {
        if (!opt_hide_banner && strcmp(name, "version") != 0) print_banner();
        log_flush();
        fputs(text, stdout);
        if (strcmp(name, "version") != 0 && strcmp(name, "L") != 0 && strcmp(name, "license") != 0 && is_info != 2) printf("\nExiting with exit code 0\n");
        else if (is_info == 2) { /* text already contains trailer */ }
        fflush(stdout);
    }
    return 1;
}

static int parse_args(int argc, char **argv)
{
    OptList cur = {0};
    /* first pass: global options can be anywhere; info options exit immediately */
    for (int i = 1; i < argc; i++) {
        const char *a = argv[i];
        if (a[0] == '-' && a[1]) {
            const char *name = a + 1;
            if (name[0] == '-' ) name++;
            char spec[64];
            const char *arg = (i + 1 < argc) ? argv[i + 1] : NULL;
            /* info options */
            {
                static const char *simple[] = { "L", "license", "version", "formats", "muxers", "demuxers", "devices", "codecs", "decoders", "encoders", "filters",
                                                "pix_fmts", "layouts", "sample_fmts", "colors", "bsfs", "protocols", "hwaccels", "dispositions", "buildconf", "sources", "sinks", NULL };
                int is_info = 0;
                for (int k = 0; simple[k]; k++) if (!strcmp(name, simple[k])) is_info = 1;
                if (!strcmp(name, "h") || !strcmp(name, "?") || !strcmp(name, "help")) is_info = 2;
                if (is_info) {
                    /* apply preceding hide_banner / loglevel only */
                    for (int j = 1; j < i; j++) if (!strcmp(argv[j], "-hide_banner")) opt_hide_banner = 1;
                    const char *harg = NULL;
                    if (is_info == 2 && arg && arg[0] != '-') harg = arg;
                    if (is_info == 1 && (!strcmp(name, "sources") || !strcmp(name, "sinks") || !strcmp(name, "buildconf"))) {
                        if (!opt_hide_banner) print_banner();
                        if (!strcmp(name, "buildconf")) printf("\n  configuration:\n    --disable-ffplay\n    --disable-ffprobe\n    --disable-autodetect\n    --enable-zlib\n    --enable-lzma\n    --enable-iconv\n\nExiting with exit code 0\n");
                        else printf("\nExiting with exit code 0\n");
                        return 1;
                    }
                    info_option(name, harg);
                    return 1;
                }
            }
            if (!strcmp(name, "i")) {
                if (!arg) { log_msg(LOG_FATAL, "Missing argument for option '%s'.\n", name); log_msg(LOG_FATAL, "Error splitting the argument list: %s\n", err_text(ERR_EINVAL)); return ERR_EINVAL; }
                infiles = realloc(infiles, sizeof(FileSpec) * (ninfiles + 1));
                infiles[ninfiles].url = strdup(arg); infiles[ninfiles].opts = cur; infiles[ninfiles].is_input = 1;
                ninfiles++;
                memset(&cur, 0, sizeof cur);
                i++;
                continue;
            }
            const OptDef *d = find_opt(name, spec, sizeof spec);
            int bool_neg = 0;
            if (!d && !strncmp(name, "no", 2)) {
                const OptDef *d2 = find_opt(name + 2, spec, sizeof spec);
                if (d2 && (d2->flags & OPT_BOOL)) { d = d2; bool_neg = 1; }
            }
            if (!d) {
                log_msg(LOG_FATAL, "Unrecognized option '%s'.\n", name);
                log_msg(LOG_FATAL, "Error splitting the argument list: %s\n", err_text(ERR_OPTION_NOT_FOUND));
                return ERR_OPTION_NOT_FOUND;
            }
            const char *val = NULL;
            if (!(d->flags & OPT_BOOL)) {
                if (!arg) {
                    log_msg(LOG_FATAL, "Missing argument for option '%s'.\n", name);
                    log_msg(LOG_FATAL, "Error splitting the argument list: %s\n", err_text(ERR_EINVAL));
                    return ERR_EINVAL;
                }
                val = arg; i++;
            } else val = bool_neg ? "0" : "1";
            if (d->flags & OPT_GLOBAL) {
                char full[128]; snprintf(full, sizeof full, "%s%s", bool_neg ? "no" : "", d->name);
                int r = handle_global_opt(full, val);
                if (r < 0) { log_msg(LOG_FATAL, "Error parsing global options: %s\n", err_text(r)); return r; }
                optlist_add(&global_opts, d->name, spec, val);
            } else {
                char full[128]; snprintf(full, sizeof full, "%s%s", bool_neg ? "no" : "", d->name);
                optlist_add(&cur, full, spec, val);
            }
        } else {
            /* output file */
            outfiles = realloc(outfiles, sizeof(FileSpec) * (noutfiles + 1));
            outfiles[noutfiles].url = strdup(a); outfiles[noutfiles].opts = cur; outfiles[noutfiles].is_input = 0;
            noutfiles++;
            memset(&cur, 0, sizeof cur);
        }
    }
    if (cur.n) {
        /* trailing options without a file */
        const char *last = cur.names[cur.n - 1];
        log_msg(LOG_WARNING, "Trailing option(s) found in the command: may be ignored.\n");
        (void)last;
    }
    return 0;
}

int main(int argc, char **argv)
{
    gettimeofday(&t_start, NULL);
    setvbuf(stderr, NULL, _IONBF, 0);
    if (argc <= 1) {
        print_banner();
        log_msg(LOG_INFO, "Universal media converter\n");
        log_msg(LOG_INFO, "usage: ffmpeg [options] [[infile options] -i infile]... {[outfile options] outfile}...\n");
        log_msg(LOG_INFO, "\nUse -h to get full help or, even better, run 'man ffmpeg'\n");
        return 1;
    }
    int r = parse_args(argc, argv);
    if (r == 1) return 0;
    if (r < 0) return exit_code_from_err(r);
    print_banner();
    /* build inputs */
    for (int i = 0; i < ninfiles; i++) {
        Input *in = calloc(1, sizeof *in);
        in->index = i;
        in->url = infiles[i].url;
        in->duration_us = -1; in->start_time_us = -1;
        OptList *ol = &infiles[i].opts;
        const char *v;
        if ((v = optlist_get(ol, "f"))) in->opt_format = strdup(v);
        if ((v = optlist_get(ol, "t"))) parse_duration_us(v, &in->opt_t_us);
        if ((v = optlist_get(ol, "ss"))) parse_duration_us(v, &in->opt_ss_us);
        if ((v = optlist_get(ol, "ar"))) in->opt_ar = atoi(v);
        if ((v = optlist_get(ol, "ac"))) in->opt_ac = atoi(v);
        if ((v = optlist_get(ol, "sample_rate"))) in->opt_ar = atoi(v);
        if ((v = optlist_get(ol, "channels"))) in->opt_ac = atoi(v);
        if ((v = optlist_get(ol, "ignore_length"))) in->ignore_length = parse_bool_opt(v);
        inputs = realloc(inputs, sizeof(Input *) * (ninputs + 1));
        inputs[ninputs++] = in;
    }
    for (int i = 0; i < noutfiles; i++) {
        Output *o = calloc(1, sizeof *o);
        o->index = i;
        o->url = outfiles[i].url;
        o->opts = outfiles[i].opts;
        const char *v;
        if ((v = optlist_get(&o->opts, "f"))) o->opt_format = strdup(v);
        if ((v = optlist_get(&o->opts, "t"))) parse_duration_us(v, &o->opt_t_us);
        if ((v = optlist_get(&o->opts, "to"))) parse_duration_us(v, &o->opt_to_us);
        if ((v = optlist_get(&o->opts, "ss"))) parse_duration_us(v, &o->opt_ss_us);
        if (optlist_has(&o->opts, "an")) o->no_audio = 1;
        if ((v = optlist_get(&o->opts, "map"))) {
            o->has_map = 1;
            /* forms: 0, 0:0, 0:a, 0:a:0 */
            char *m = strdup(v); char *p = m;
            int neg = 0; if (*p == '-') { neg = 1; p++; }
            o->map_file = atoi(p);
            char *c = strchr(p, ':');
            o->map_stream = 0;
            if (c) {
                c++;
                if (*c == 'a' || *c == 'v' || *c == 's' || *c == 'd') {
                    if (*c != 'a') o->map_stream = 99;
                    char *c2 = strchr(c, ':'); if (c2) o->map_stream += atoi(c2 + 1);
                } else o->map_stream = atoi(c);
            }
            if (neg) o->no_audio = 1;
            free(m);
        }
        outputs = realloc(outputs, sizeof(Output *) * (noutputs + 1));
        outputs[noutputs++] = o;
    }
    if (ninputs == 0 && noutputs == 0) {
        log_msg(LOG_INFO, "Universal media converter\n");
        log_msg(LOG_INFO, "usage: ffmpeg [options] [[infile options] -i infile]... {[outfile options] outfile}...\n");
        log_msg(LOG_INFO, "\nUse -h to get full help or, even better, run 'man ffmpeg'\n");
        return 1;
    }
    int ret = run();
    log_flush();
    if (ret == 1) return 1;
    if (ret == ERR_EXIT) return 0;
    if (ret < 0) return exit_code_from_err(ret);
    return 0;
}
